/**
 * Customer Quote Service — Sage-parity quotes with convert-to-invoice
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface QuoteLine {
  id: string;
  quoteId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
  accountId: string | null;
}

export interface Quote {
  id: string;
  quoteNumber: string;
  clientId: string | null;
  customerName: string;
  quoteDate: string;
  expiryDate: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  total: number;
  notes: string | null;
  terms: string | null;
  convertedInvoiceId: string | null;
  createdAt: string;
  updatedAt: string;
  lines?: QuoteLine[];
}

interface QuoteFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface QuoteInput {
  customerName: string;
  clientId?: string;
  quoteDate?: string;
  expiryDate?: string;
  notes?: string;
  terms?: string;
  lines: { description: string; quantity: number; unitPrice: number; taxRate?: number; accountId?: string }[];
}

function mapQuote(r: Row): Quote {
  return {
    id: r.id, quoteNumber: r.quote_number, clientId: r.client_id,
    customerName: r.customer_name, quoteDate: r.quote_date,
    expiryDate: r.expiry_date, status: r.status,
    subtotal: Number(r.subtotal), taxAmount: Number(r.tax_amount),
    total: Number(r.total), notes: r.notes, terms: r.terms,
    convertedInvoiceId: r.converted_invoice_id,
    createdAt: r.created_at, updatedAt: r.updated_at,
  };
}

function mapLine(r: Row): QuoteLine {
  return {
    id: r.id, quoteId: r.quote_id, lineNumber: r.line_number,
    description: r.description, quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price), taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total), accountId: r.account_id,
  };
}

async function nextQuoteNumber(): Promise<string> {
  const rows = (await sql`
    SELECT quote_number FROM customer_quotes ORDER BY created_at DESC LIMIT 1
  `) as Row[];
  if (rows.length === 0) return 'QUO-00001';
  const last = rows[0].quote_number;
  const num = parseInt(last.replace('QUO-', ''), 10) || 0;
  return `QUO-${String(num + 1).padStart(5, '0')}`;
}

function calcTotals(lines: QuoteInput['lines']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const l of lines) {
    const lt = l.quantity * l.unitPrice;
    subtotal += lt;
    taxAmount += lt * ((l.taxRate ?? 15) / 100);
  }
  return { subtotal: Math.round(subtotal * 100) / 100, taxAmount: Math.round(taxAmount * 100) / 100, total: Math.round((subtotal + taxAmount) * 100) / 100 };
}

export async function getQuotes(filters?: QuoteFilters): Promise<{ quotes: Quote[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT * FROM customer_quotes
      WHERE (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes
      WHERE (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes WHERE status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM customer_quotes ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_quotes`) as Row[];
  }
  return { quotes: rows.map(mapQuote), total: Number(countRows[0]?.cnt || 0) };
}

export async function getQuote(id: string): Promise<Quote | null> {
  const rows = (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID`) as Row[];
  if (rows.length === 0) return null;
  const quote = mapQuote(rows[0]);
  const lineRows = (await sql`
    SELECT * FROM customer_quote_lines WHERE quote_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  quote.lines = lineRows.map(mapLine);
  return quote;
}

export async function createQuote(input: QuoteInput, userId?: string): Promise<Quote> {
  const quoteNumber = await nextQuoteNumber();
  const { subtotal, taxAmount, total } = calcTotals(input.lines);
  const qd = input.quoteDate || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_quotes (quote_number, client_id, customer_name, quote_date, expiry_date,
      subtotal, tax_amount, total, notes, terms, created_by)
    VALUES (${quoteNumber}, ${input.clientId || null}, ${input.customerName}, ${qd},
      ${input.expiryDate || null}, ${subtotal}, ${taxAmount}, ${total},
      ${input.notes || null}, ${input.terms || null}, ${userId || null})
    RETURNING *
  `) as Row[];

  const quote = mapQuote(rows[0]);
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${quote.id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote created', { quoteNumber, total });
  return (await getQuote(quote.id))!;
}

export async function updateQuote(id: string, input: QuoteInput): Promise<Quote | null> {
  const existing = await getQuote(id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, total } = calcTotals(input.lines);

  await sql`
    UPDATE customer_quotes SET customer_name = ${input.customerName}, client_id = ${input.clientId || null},
      quote_date = ${input.quoteDate || existing.quoteDate}, expiry_date = ${input.expiryDate || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total = ${total},
      notes = ${input.notes || null}, terms = ${input.terms || null}, updated_at = NOW()
    WHERE id = ${id}::UUID AND status = 'draft'
  `;
  await sql`DELETE FROM customer_quote_lines WHERE quote_id = ${id}::UUID`;
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote updated', { id });
  return getQuote(id);
}

export async function deleteQuote(id: string): Promise<boolean> {
  const rows = (await sql`DELETE FROM customer_quotes WHERE id = ${id}::UUID AND status = 'draft' RETURNING id`) as Row[];
  return rows.length > 0;
}

export async function updateQuoteStatus(id: string, status: string): Promise<Quote | null> {
  await sql`UPDATE customer_quotes SET status = ${status}, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Quote status changed', { id, status });
  return getQuote(id);
}

export async function convertToInvoice(id: string, userId?: string): Promise<{ quote: Quote; invoiceId: string } | null> {
  const quote = await getQuote(id);
  if (!quote || quote.status !== 'accepted') return null;

  // Create invoice from quote
  const invRows = (await sql`
    INSERT INTO customer_invoices (client_id, invoice_date, due_date, subtotal, tax_amount, total, notes, status, created_by)
    VALUES (${quote.clientId}, ${quote.quoteDate}, ${quote.expiryDate || quote.quoteDate}, ${quote.subtotal},
      ${quote.taxAmount}, ${quote.total}, ${'Converted from ' + quote.quoteNumber}, 'draft', ${userId || null})
    RETURNING id
  `) as Row[];
  const invoiceId = invRows[0].id;

  // Copy lines
  for (const line of quote.lines || []) {
    await sql`
      INSERT INTO customer_invoice_items (invoice_id, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${invoiceId}::UUID, ${line.description}, ${line.quantity}, ${line.unitPrice}, ${line.taxRate}, ${line.lineTotal}, ${line.accountId})
    `;
  }

  await sql`UPDATE customer_quotes SET status = 'converted', converted_invoice_id = ${invoiceId}::UUID, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Quote converted to invoice', { quoteId: id, invoiceId });
  return { quote: (await getQuote(id))!, invoiceId };
}

/**
 * PRD-060: GL Integration Hooks
 * Auto-post GL entries when existing modules trigger financial events
 *
 * Hooks:
 * - Customer invoice approved → DR AR, CR Revenue
 * - Customer payment recorded → DR Bank, CR AR
 * - GRN confirmed → DR Materials, CR AP
 * - PO approved → DR Materials, CR AP (commitment accounting)
 * - Asset depreciation → DR Depreciation Expense, CR Accumulated Depreciation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// GL account codes (from seeded chart of accounts)
const ACCOUNTS = {
  BANK: '1110',
  AR: '1120',
  VAT_INPUT: '1140',
  AP: '2110',
  VAT_OUTPUT: '2120',
  ACTIVATION_REVENUE: '4100',
  MATERIALS: '5100',
} as const;

async function getAccountId(code: string): Promise<string> {
  const rows = (await sql`SELECT id FROM gl_accounts WHERE account_code = ${code} LIMIT 1`) as Row[];
  if (!rows[0]) throw new Error(`GL account ${code} not found`);
  return String(rows[0].id);
}

// ── Customer Invoice Approved → GL ──────────────────────────────────────────

export async function postCustomerInvoiceToGL(
  invoiceId: string,
  projectId: string,
  userId: string
): Promise<string | null> {
  try {
    // Check if already posted
    const inv = (await sql`
      SELECT id, invoice_number, total_amount, tax_amount, subtotal, gl_journal_entry_id
      FROM customer_invoices WHERE id = ${invoiceId}
    `) as Row[];

    if (!inv[0]) { log.warn('Invoice not found for GL posting', { invoiceId }, 'accounting'); return null; }
    if (inv[0].gl_journal_entry_id) return String(inv[0].gl_journal_entry_id); // Already posted

    const totalAmount = Number(inv[0].total_amount || 0);
    const taxAmount = Number(inv[0].tax_amount || 0);
    const subtotal = Number(inv[0].subtotal || totalAmount - taxAmount);
    if (totalAmount === 0) return null;

    const arId = await getAccountId(ACCOUNTS.AR);
    const revenueId = await getAccountId(ACCOUNTS.ACTIVATION_REVENUE);
    const vatOutputId = await getAccountId(ACCOUNTS.VAT_OUTPUT);

    // Create journal entry: DR AR (total), CR Revenue (subtotal), CR VAT Output (tax)
    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${`CI-${inv[0].invoice_number}`}, CURRENT_DATE,
        ${`Customer invoice ${inv[0].invoice_number} approved`},
        'auto_invoice', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    // DR Accounts Receivable (full amount)
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
      VALUES (${entryId}::UUID, ${arId}::UUID, ${totalAmount}, 0,
        ${`Invoice ${inv[0].invoice_number}`}, ${projectId}::UUID)
    `;

    // CR Revenue (subtotal excl VAT)
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
      VALUES (${entryId}::UUID, ${revenueId}::UUID, 0, ${subtotal},
        ${`Invoice ${inv[0].invoice_number}`}, ${projectId}::UUID)
    `;

    // CR VAT Output (if tax > 0)
    if (taxAmount > 0.01) {
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
        VALUES (${entryId}::UUID, ${vatOutputId}::UUID, 0, ${taxAmount},
          ${`VAT on invoice ${inv[0].invoice_number}`}, ${projectId}::UUID)
      `;
    }

    // Link journal entry back to invoice
    await sql`UPDATE customer_invoices SET gl_journal_entry_id = ${entryId}::UUID WHERE id = ${invoiceId}`;

    log.info('Customer invoice GL posted', { invoiceId, entryId, totalAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post customer invoice to GL', { invoiceId, error: err }, 'accounting');
    return null; // Non-blocking — invoice still approved even if GL fails
  }
}

// ── Customer Payment Recorded → GL ──────────────────────────────────────────

export async function postCustomerPaymentToGL(
  invoiceId: string,
  paymentAmount: number,
  projectId: string,
  userId: string
): Promise<string | null> {
  try {
    if (paymentAmount <= 0) return null;

    const inv = (await sql`
      SELECT invoice_number FROM customer_invoices WHERE id = ${invoiceId}
    `) as Row[];
    if (!inv[0]) return null;

    const bankId = await getAccountId(ACCOUNTS.BANK);
    const arId = await getAccountId(ACCOUNTS.AR);

    // DR Bank, CR AR
    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${`CPAY-${inv[0].invoice_number}-${Date.now()}`}, CURRENT_DATE,
        ${`Payment received for invoice ${inv[0].invoice_number}`},
        'auto_payment', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
      VALUES (${entryId}::UUID, ${bankId}::UUID, ${paymentAmount}, 0,
        ${`Payment: invoice ${inv[0].invoice_number}`}, ${projectId}::UUID)
    `;
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
      VALUES (${entryId}::UUID, ${arId}::UUID, 0, ${paymentAmount},
        ${`Payment: invoice ${inv[0].invoice_number}`}, ${projectId}::UUID)
    `;

    log.info('Customer payment GL posted', { invoiceId, entryId, paymentAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post customer payment to GL', { invoiceId, error: err }, 'accounting');
    return null;
  }
}

// ── GRN Confirmed → GL ─────────────────────────────────────────────────────

export async function postGRNToGL(
  grnId: string,
  totalValue: number,
  projectId: string | null,
  userId: string,
  grnNumber: string
): Promise<string | null> {
  try {
    if (totalValue <= 0) return null;

    const materialsId = await getAccountId(ACCOUNTS.MATERIALS);
    const apId = await getAccountId(ACCOUNTS.AP);

    // DR Materials/Inventory, CR AP
    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${`GRN-${grnNumber}`}, CURRENT_DATE,
        ${`GRN ${grnNumber} confirmed — goods received`},
        'auto_grn', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    if (projectId) {
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
        VALUES (${entryId}::UUID, ${materialsId}::UUID, ${totalValue}, 0,
          ${`GRN ${grnNumber}`}, ${projectId}::UUID)
      `;
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
        VALUES (${entryId}::UUID, ${apId}::UUID, 0, ${totalValue},
          ${`GRN ${grnNumber}`}, ${projectId}::UUID)
      `;
    } else {
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
        VALUES (${entryId}::UUID, ${materialsId}::UUID, ${totalValue}, 0, ${`GRN ${grnNumber}`})
      `;
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
        VALUES (${entryId}::UUID, ${apId}::UUID, 0, ${totalValue}, ${`GRN ${grnNumber}`})
      `;
    }

    log.info('GRN GL posted', { grnId, entryId, totalValue, grnNumber }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post GRN to GL', { grnId, error: err }, 'accounting');
    return null;
  }
}

// Re-export Phase 4 cross-module hooks
