          WHERE ga.account_name ILIKE '%receivable%'
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        arChangeVal = Number(arChange?.change || 0);
      }
    } catch { arChangeVal = 0; }

    // Changes in AP (payable)
    let apChangeVal = 0;
