            AND je.entry_date <= ${endDate}
        `;
        apChangeVal = Number(apChange?.change || 0);
      }
    } catch { apChangeVal = 0; }

    // Investing: fixed asset changes
    let investingChangeVal = 0;
    try {
      if (hasSubtype) {
