/**
 * Year-End Processing API
 * GET /api/accounting/year-end - List fiscal years with status
 * POST /api/accounting/year-end - Close a fiscal year (create closing journal)
 * Sage equivalent: Accountant's Area > Year-End
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      // Group fiscal periods by year label
      const years = await sql`
        SELECT
          fiscal_year as year_label,
          MIN(start_date) as start_date,
          MAX(end_date) as end_date,
          COUNT(*) FILTER (WHERE status = 'open')::int as periods_open,
          COUNT(*) FILTER (WHERE status IN ('closed', 'locked'))::int as periods_closed,
          CASE
            WHEN COUNT(*) FILTER (WHERE status = 'open') = 0
             AND COUNT(*) FILTER (WHERE status IN ('closed', 'locked')) > 0
            THEN 'all_closed'
            ELSE 'open'
          END as status
        FROM fiscal_periods
        GROUP BY fiscal_year
        ORDER BY MIN(start_date) DESC
      `;

      // Get revenue/expense totals per year
      const yearsWithTotals = await Promise.all(years.map(async (fy) => {
        const [rev] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as total
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'revenue'
            AND je.status = 'posted'
            AND je.entry_date >= ${fy.start_date}
            AND je.entry_date <= ${fy.end_date}
        `;
        const [exp] = await sql`
          SELECT COALESCE(SUM(jl.debit - jl.credit), 0)::numeric as total
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'expense'
            AND je.status = 'posted'
            AND je.entry_date >= ${fy.start_date}
            AND je.entry_date <= ${fy.end_date}
        `;

        return {
          ...fy,
          periods_open: Number(fy.periods_open),
          periods_closed: Number(fy.periods_closed),
          total_revenue: Number(rev.total),
          total_expenses: Number(exp.total),
          net_income: Number(rev.total) - Number(exp.total),
        };
      }));

      return apiResponse.success(res, { years: yearsWithTotals });
    } catch (err) {
      log.error('Failed to fetch fiscal years', { error: err, module: 'accounting' });
      return apiResponse.databaseError(res, err, 'Failed to fetch fiscal years');
    }
  }

  if (req.method === 'POST') {
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    const { yearLabel, action } = req.body;

    if (action !== 'close') {
      return apiResponse.badRequest(res, 'Only "close" action is supported');
    }

    if (!yearLabel) {
      return apiResponse.validationError(res, { yearLabel: 'Fiscal year label required' });
    }

    try {
      // Check all periods are closed
      const openPeriods = await sql`
        SELECT COUNT(*)::int as cnt FROM fiscal_periods
        WHERE fiscal_year = ${yearLabel} AND status = 'open'
      `;

      if (Number(openPeriods[0].cnt) > 0) {
        return apiResponse.badRequest(res, `${openPeriods[0].cnt} periods still open. Close all periods first.`);
      }

      // Get year date range
      const [yearRange] = await sql`
        SELECT MIN(start_date) as start_date, MAX(end_date) as end_date
        FROM fiscal_periods WHERE fiscal_year = ${yearLabel}
      `;

      // Calculate net income (Revenue - Expenses)
      const revenueAccounts = await sql`
        SELECT ga.id, ga.account_code, ga.account_name,
          COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as balance
        FROM gl_accounts ga
        LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
        LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          AND je.status = 'posted'
          AND je.entry_date >= ${yearRange.start_date}
          AND je.entry_date <= ${yearRange.end_date}
        WHERE ga.account_type = 'revenue'
        GROUP BY ga.id, ga.account_code, ga.account_name
        HAVING COALESCE(SUM(jl.credit - jl.debit), 0) != 0
      `;

      const expenseAccounts = await sql`
        SELECT ga.id, ga.account_code, ga.account_name,
          COALESCE(SUM(jl.debit - jl.credit), 0)::numeric as balance
        FROM gl_accounts ga
        LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
        LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          AND je.status = 'posted'
          AND je.entry_date >= ${yearRange.start_date}
          AND je.entry_date <= ${yearRange.end_date}
        WHERE ga.account_type = 'expense'
        GROUP BY ga.id, ga.account_code, ga.account_name
        HAVING COALESCE(SUM(jl.debit - jl.credit), 0) != 0
      `;

      const totalRevenue = revenueAccounts.reduce((s, a) => s + Number(a.balance), 0);
      const totalExpenses = expenseAccounts.reduce((s, a) => s + Number(a.balance), 0);
      const netIncome = totalRevenue - totalExpenses;

      // Find retained earnings account — configurable via app_settings or default 3200
      let reAccountCode = '3200';
      try {
        const settingRows = await sql`SELECT value FROM app_settings WHERE key = 'retained_earnings_account'`;
        if (settingRows[0]?.value) reAccountCode = String(settingRows[0].value);
      } catch (e) { log.warn('Failed to load retained_earnings_account setting', { error: e }, 'accounting'); }

      const reRows = await sql`
        SELECT id FROM gl_accounts
        WHERE account_code = ${reAccountCode} OR account_name ILIKE '%retained earnings%'
        LIMIT 1
      `;
      const retainedEarnings = reRows[0];

      if (!retainedEarnings) {
        return apiResponse.badRequest(res, `Retained Earnings account not found (${reAccountCode}). Create the account or set 'retained_earnings_account' in app_settings.`);
      }

      // Create closing journal entry
      const totalDebit = totalRevenue + (netIncome < 0 ? Math.abs(netIncome) : 0);
      const totalCredit = totalExpenses + (netIncome >= 0 ? netIncome : 0);

      const [closingEntry] = await sql`
        INSERT INTO gl_journal_entries (
          id, entry_number, entry_date, description,
          source, status, total_debit, total_credit,
          created_by, created_at
        ) VALUES (
          gen_random_uuid(),
          ${'YE-' + yearLabel},
          ${yearRange.end_date},
          ${'Year-End Closing: ' + yearLabel},
          'year_end', 'posted',
          ${totalDebit}, ${totalCredit},
          ${userId}, NOW()
        )
        RETURNING *
      `;

      // DR Revenue accounts (to zero them)
      for (const rev of revenueAccounts) {
        await sql`
          INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
          VALUES (gen_random_uuid(), ${closingEntry.id}, ${rev.id}, ${Number(rev.balance)}, 0, 'Year-end close', NOW())
        `;
      }

      // CR Expense accounts (to zero them)
      for (const exp of expenseAccounts) {
        await sql`
          INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
          VALUES (gen_random_uuid(), ${closingEntry.id}, ${exp.id}, 0, ${Number(exp.balance)}, 'Year-end close', NOW())
        `;
      }

      // Net income → Retained Earnings
      if (netIncome >= 0) {
        await sql`
          INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
          VALUES (gen_random_uuid(), ${closingEntry.id}, ${retainedEarnings.id}, 0, ${netIncome}, 'Net income to retained earnings', NOW())
        `;
      } else {
        await sql`
          INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
          VALUES (gen_random_uuid(), ${closingEntry.id}, ${retainedEarnings.id}, ${Math.abs(netIncome)}, 0, 'Net loss to retained earnings', NOW())
        `;
      }

      // Lock all periods
      await sql`
        UPDATE fiscal_periods SET status = 'locked' WHERE fiscal_year = ${yearLabel}
      `;

      log.info('Year-end processed', {
        year: yearLabel,
        entryId: closingEntry.id,
        netIncome,
        module: 'accounting',
      });

      return apiResponse.success(res, {
        closingEntry,
        netIncome,
        message: `Year ${yearLabel} closed. Net income R${netIncome.toFixed(2)} transferred to Retained Earnings.`,
      });
    } catch (err) {
      log.error('Failed to process year-end', { error: err, yearLabel, module: 'accounting' });
      return apiResponse.databaseError(res, err, 'Failed to process year-end');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Customer Receipt Allocations API
 * GET  — List existing allocations (audit trail)
 * POST — Allocate receipts against outstanding invoices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

interface AllocationItem {
  invoiceId: string;
  amount: number;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const paymentId = req.query.payment_id as string | undefined;
      const clientId = req.query.client_id as string | undefined;

      let rows;
      if (paymentId) {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.company_name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN clients c ON c.id = cp.client_id
          WHERE cpa.payment_id = ${paymentId}
          ORDER BY cpa.created_at DESC
        `;
      } else if (clientId) {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.company_name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN clients c ON c.id = cp.client_id
          WHERE cp.client_id = ${clientId}
          ORDER BY cpa.created_at DESC
          LIMIT 200
        `;
      } else {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.company_name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN clients c ON c.id = cp.client_id
          ORDER BY cpa.created_at DESC
          LIMIT 200
        `;
      }

      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to get customer allocations', { error: err });
      return apiResponse.badRequest(res, 'Failed to get allocations');
    }
  }

  if (req.method === 'POST') {
    try {
      const { paymentId, allocations } = req.body as {
        paymentId?: string;
        allocations?: AllocationItem[];
      };

      if (!paymentId) return apiResponse.badRequest(res, 'paymentId is required');
      if (!allocations || !Array.isArray(allocations) || allocations.length === 0) {
        return apiResponse.badRequest(res, 'allocations array is required');
      }

      // Validate allocation items
      for (const alloc of allocations) {
        if (!alloc.invoiceId || !alloc.amount || alloc.amount <= 0) {
          return apiResponse.badRequest(res, 'Each allocation needs invoiceId and positive amount');
        }
      }

      // Fetch payment
      const paymentRows = await sql`
        SELECT cp.id, cp.client_id, cp.total_amount, cp.status,
          COALESCE((SELECT SUM(amount_allocated) FROM customer_payment_allocations WHERE payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp WHERE cp.id = ${paymentId}
      `;
      const payment = paymentRows[0];
      if (!payment) return apiResponse.notFound(res, 'Payment', paymentId);
      if (payment.status === 'cancelled') {
        return apiResponse.badRequest(res, 'Cannot allocate a cancelled payment');
      }

      const currentAllocated = Number(payment.allocated_amount || 0);
      const totalPayment = Number(payment.total_amount);
      const allocTotal = allocations.reduce((s, a) => s + a.amount, 0);

      if (currentAllocated + allocTotal > totalPayment + 0.01) {
        return apiResponse.badRequest(res, `Allocation total (${allocTotal}) exceeds available balance (${(totalPayment - currentAllocated).toFixed(2)})`);
      }

      // Process each allocation
      const results: { invoiceId: string; amount: number; newStatus: string }[] = [];

      for (const alloc of allocations) {
        // Validate invoice belongs to same client
        const invoiceRows = await sql`
          SELECT id, client_id, total_amount, amount_paid, status
          FROM customer_invoices WHERE id = ${alloc.invoiceId}
        `;
        const invoice = invoiceRows[0];
        if (!invoice) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} not found`);
        }
        if (invoice.client_id !== payment.client_id) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} belongs to a different client`);
        }

        const outstanding = Number(invoice.total_amount) - Number(invoice.amount_paid || 0);
        if (alloc.amount > outstanding + 0.01) {
          return apiResponse.badRequest(res, `Allocation ${alloc.amount} exceeds outstanding ${outstanding.toFixed(2)} for invoice ${alloc.invoiceId}`);
        }

        // Insert allocation record
        await sql`
          INSERT INTO customer_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}, ${alloc.invoiceId}, ${alloc.amount})
        `;

        // Update invoice amount_paid
        const newPaid = Number(invoice.amount_paid || 0) + alloc.amount;
        const invoiceTotal = Number(invoice.total_amount);
        const newStatus = newPaid >= invoiceTotal - 0.01 ? 'paid' : 'partially_paid';

        await sql`
          UPDATE customer_invoices
          SET amount_paid = ${newPaid}, status = ${newStatus}
          WHERE id = ${alloc.invoiceId}
        `;

        results.push({ invoiceId: alloc.invoiceId, amount: alloc.amount, newStatus });
      }

      // Update payment allocated_amount
      const newAllocated = currentAllocated + allocTotal;
      const paymentStatus = newAllocated >= totalPayment - 0.01 ? 'reconciled' : 'confirmed';

      await sql`
        UPDATE customer_payments
        SET status = ${paymentStatus}
        WHERE id = ${paymentId}
      `;

      log.info('Customer allocations created', {
        paymentId,
        count: results.length,
        total: allocTotal,
      });

      return apiResponse.success(res, {
        paymentId,
        allocations: results,
        newAllocatedAmount: newAllocated,
        paymentStatus,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Allocation failed';
      log.error('Customer allocation failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(handler);

/**
 * Supplier Payment Allocations API
 * GET  — List existing allocations (audit trail)
 * POST — Allocate payments against outstanding supplier invoices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

interface AllocationItem {
  invoiceId: string;
  amount: number;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const paymentId = req.query.payment_id as string | undefined;
      const supplierId = req.query.supplier_id as string | undefined;

      let rows;
      if (paymentId) {
        rows = await sql`
          SELECT spa.id, spa.payment_id, spa.invoice_id, spa.amount_allocated AS amount,
            spa.created_at AS allocated_at, sp.payment_number, si.invoice_number,
            s.company_name AS supplier_name
          FROM supplier_payment_allocations spa
          JOIN supplier_payments sp ON sp.id = spa.payment_id
          JOIN supplier_invoices si ON si.id = spa.invoice_id
          JOIN suppliers s ON s.id = sp.supplier_id
          WHERE spa.payment_id = ${paymentId}
          ORDER BY spa.created_at DESC
        `;
      } else if (supplierId) {
        rows = await sql`
          SELECT spa.id, spa.payment_id, spa.invoice_id, spa.amount_allocated AS amount,
            spa.created_at AS allocated_at, sp.payment_number, si.invoice_number,
            s.company_name AS supplier_name
          FROM supplier_payment_allocations spa
          JOIN supplier_payments sp ON sp.id = spa.payment_id
          JOIN supplier_invoices si ON si.id = spa.invoice_id
          JOIN suppliers s ON s.id = sp.supplier_id
          WHERE sp.supplier_id = ${supplierId}
          ORDER BY spa.created_at DESC
          LIMIT 200
        `;
      } else {
        rows = await sql`
          SELECT spa.id, spa.payment_id, spa.invoice_id, spa.amount_allocated AS amount,
            spa.created_at AS allocated_at, sp.payment_number, si.invoice_number,
            s.company_name AS supplier_name
          FROM supplier_payment_allocations spa
          JOIN supplier_payments sp ON sp.id = spa.payment_id
          JOIN supplier_invoices si ON si.id = spa.invoice_id
          JOIN suppliers s ON s.id = sp.supplier_id
          ORDER BY spa.created_at DESC
          LIMIT 200
        `;
      }

      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to get supplier allocations', { error: err });
      return apiResponse.badRequest(res, 'Failed to get allocations');
    }
  }

  if (req.method === 'POST') {
    try {
      const { paymentId, allocations } = req.body as {
        paymentId?: string;
        allocations?: AllocationItem[];
      };

      if (!paymentId) return apiResponse.badRequest(res, 'paymentId is required');
      if (!allocations || !Array.isArray(allocations) || allocations.length === 0) {
        return apiResponse.badRequest(res, 'allocations array is required');
      }

      for (const alloc of allocations) {
        if (!alloc.invoiceId || !alloc.amount || alloc.amount <= 0) {
          return apiResponse.badRequest(res, 'Each allocation needs invoiceId and positive amount');
        }
      }

      const paymentRows = await sql`
        SELECT sp.id, sp.supplier_id, sp.total_amount, sp.status,
          COALESCE((SELECT SUM(amount_allocated) FROM supplier_payment_allocations WHERE payment_id = sp.id), 0) AS allocated_amount
        FROM supplier_payments sp WHERE sp.id = ${paymentId}
      `;
      const payment = paymentRows[0];
      if (!payment) return apiResponse.notFound(res, 'Payment', paymentId);
      if (payment.status === 'cancelled') {
        return apiResponse.badRequest(res, 'Cannot allocate a cancelled payment');
      }

      const currentAllocated = Number(payment.allocated_amount || 0);
      const totalPayment = Number(payment.total_amount);
      const allocTotal = allocations.reduce((s, a) => s + a.amount, 0);

      if (currentAllocated + allocTotal > totalPayment + 0.01) {
        return apiResponse.badRequest(res, `Allocation total (${allocTotal}) exceeds available balance (${(totalPayment - currentAllocated).toFixed(2)})`);
      }

      const results: { invoiceId: string; amount: number; newStatus: string }[] = [];

      for (const alloc of allocations) {
        const invoiceRows = await sql`
          SELECT id, supplier_id, total_amount, amount_paid, status
          FROM supplier_invoices WHERE id = ${alloc.invoiceId}
        `;
        const invoice = invoiceRows[0];
        if (!invoice) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} not found`);
        }
        if (invoice.supplier_id !== payment.supplier_id) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} belongs to a different supplier`);
        }

        const outstanding = Number(invoice.total_amount) - Number(invoice.amount_paid || 0);
        if (alloc.amount > outstanding + 0.01) {
          return apiResponse.badRequest(res, `Allocation ${alloc.amount} exceeds outstanding ${outstanding.toFixed(2)} for invoice ${alloc.invoiceId}`);
        }

        await sql`
          INSERT INTO supplier_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}, ${alloc.invoiceId}, ${alloc.amount})
        `;

        const newPaid = Number(invoice.amount_paid || 0) + alloc.amount;
        const invoiceTotal = Number(invoice.total_amount);
        const newStatus = newPaid >= invoiceTotal - 0.01 ? 'paid' : 'partially_paid';

        await sql`
          UPDATE supplier_invoices
          SET amount_paid = ${newPaid}, status = ${newStatus}
          WHERE id = ${alloc.invoiceId}
        `;

        results.push({ invoiceId: alloc.invoiceId, amount: alloc.amount, newStatus });
      }

      const newAllocated = currentAllocated + allocTotal;
      const paymentStatus = newAllocated >= totalPayment - 0.01 ? 'reconciled' : 'approved';

      await sql`
        UPDATE supplier_payments
        SET status = ${paymentStatus}
        WHERE id = ${paymentId}
      `;

      log.info('Supplier allocations created', {
        paymentId,
        count: results.length,
        total: allocTotal,
      });

      return apiResponse.success(res, {
        paymentId,
        allocations: results,
        newAllocatedAmount: newAllocated,
        paymentStatus,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Allocation failed';
      log.error('Supplier allocation failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

