/**
 * Bank Transfers API
 * POST /api/accounting/bank-transfers - Transfer between bank accounts
 * Creates a balanced journal entry: DR destination bank, CR source bank
 * Sage equivalent: Banking > Transfers
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { fromAccountId, toAccountId, amount, reference, transferDate } = req.body;

  if (!fromAccountId || !toAccountId || !amount) {
    return apiResponse.validationError(res, {
      fromAccountId: !fromAccountId ? 'Required' : undefined,
      toAccountId: !toAccountId ? 'Required' : undefined,
      amount: !amount ? 'Required' : undefined,
    });
  }

  if (fromAccountId === toAccountId) {
    return apiResponse.badRequest(res, 'Source and destination accounts must be different');
  }

  if (Number(amount) <= 0) {
    return apiResponse.badRequest(res, 'Transfer amount must be positive');
  }

  try {
    // Verify both accounts exist and are bank accounts
    const accounts = await sql`
      SELECT id, account_code, account_name, account_subtype
      FROM gl_accounts
      WHERE id IN (${fromAccountId}, ${toAccountId})
    `;

    if (accounts.length !== 2) {
      return apiResponse.badRequest(res, 'One or both accounts not found');
    }

    const fromAcct = accounts.find(a => a.id === fromAccountId);
    const toAcct = accounts.find(a => a.id === toAccountId);

    // Get current fiscal period
    const [period] = await sql`
      SELECT id FROM fiscal_periods
      WHERE status = 'open'
      ORDER BY start_date DESC
      LIMIT 1
    `;

    // Create journal entry
    const entryRef = reference || `Transfer: ${fromAcct?.account_name} → ${toAcct?.account_name}`;
    const txDate = transferDate || new Date().toISOString().split('T')[0];

    const [entry] = await sql`
      INSERT INTO gl_journal_entries (
        id, entry_number, entry_date, description,
        source, status, fiscal_period_id,
        total_debit, total_credit,
        created_by, created_at
      ) VALUES (
        gen_random_uuid(),
        'TXF-' || LPAD((SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM 5) AS INTEGER)), 0) + 1 FROM gl_journal_entries WHERE entry_number LIKE 'TXF-%')::text, 4, '0'),
        ${txDate}, ${entryRef},
        'bank_transfer', 'posted', ${period?.id || null},
        ${Number(amount)}, ${Number(amount)},
        ${userId}, NOW()
      )
      RETURNING *
    `;

    // Create journal lines: DR destination, CR source
    await sql`
      INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
      VALUES
        (gen_random_uuid(), ${entry.id}, ${toAccountId}, ${Number(amount)}, 0, ${`Transfer from ${fromAcct?.account_name}`}, NOW()),
        (gen_random_uuid(), ${entry.id}, ${fromAccountId}, 0, ${Number(amount)}, ${`Transfer to ${toAcct?.account_name}`}, NOW())
    `;

    log.info('Bank transfer completed', {
      entryId: entry.id,
      from: fromAcct?.account_code,
      to: toAcct?.account_code,
      amount,
      module: 'accounting',
    });

    return apiResponse.success(res, {
      journalEntry: entry,
      message: `Transferred R${Number(amount).toFixed(2)} from ${fromAcct?.account_name} to ${toAcct?.account_name}`,
    });
  } catch (err) {
    log.error('Failed to process bank transfer', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to process bank transfer');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Opening Balances API
 * GET /api/accounting/opening-balances - Get posting-level accounts for balance entry
 * POST /api/accounting/opening-balances - Save opening balances as journal entry
 * Sage equivalent: Accountant's Area > Opening Balances
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      // Get all posting-level (level 3) accounts
      const accounts = await sql`
        SELECT
          id, account_code, account_name, account_type,
          normal_balance, is_active
        FROM gl_accounts
        WHERE level = 3 AND is_active = true
        ORDER BY account_code
      `;

      return apiResponse.success(res, {
        accounts: accounts.map(a => ({
          ...a,
          opening_debit: 0,
          opening_credit: 0,
        })),
      });
    } catch (err) {
      log.error('Failed to fetch accounts for opening balances', { error: err, module: 'accounting' });
      return apiResponse.databaseError(res, err, 'Failed to fetch accounts');
    }
  }

  if (req.method === 'POST') {
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    const { balances } = req.body;

    if (!balances || !Array.isArray(balances) || balances.length === 0) {
      return apiResponse.validationError(res, { balances: 'Array of {accountId, debit, credit} required' });
    }

    // Validate DR = CR
    const totalDebit = balances.reduce((sum: number, b: { debit: number }) => sum + Number(b.debit || 0), 0);
    const totalCredit = balances.reduce((sum: number, b: { credit: number }) => sum + Number(b.credit || 0), 0);

    if (Math.abs(totalDebit - totalCredit) > 0.01) {
      return apiResponse.badRequest(res, `Debits (${totalDebit.toFixed(2)}) must equal Credits (${totalCredit.toFixed(2)})`);
    }

    try {
      // Get first open fiscal period
      const [period] = await sql`
        SELECT id FROM fiscal_periods
        WHERE status = 'open'
        ORDER BY start_date ASC
        LIMIT 1
      `;

      // Create opening balance journal entry
      const [entry] = await sql`
        INSERT INTO gl_journal_entries (
          id, entry_number, entry_date, description,
          source, status, fiscal_period_id,
          total_debit, total_credit,
          created_by, created_at
        ) VALUES (
          gen_random_uuid(),
          'OB-' || LPAD((SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM 4) AS INTEGER)), 0) + 1 FROM gl_journal_entries WHERE entry_number LIKE 'OB-%')::text, 4, '0'),
          COALESCE((SELECT start_date FROM fiscal_periods WHERE id = ${period?.id || null}), CURRENT_DATE),
          'Opening Balances',
          'opening_balance', 'posted', ${period?.id || null},
          ${totalDebit}, ${totalCredit},
          ${userId}, NOW()
        )
        RETURNING *
      `;

      // Create journal lines
      for (const b of balances as { accountId: string; debit: number; credit: number }[]) {
        if (Number(b.debit) > 0 || Number(b.credit) > 0) {
          await sql`
            INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
            VALUES (gen_random_uuid(), ${entry.id}, ${b.accountId}, ${Number(b.debit) || 0}, ${Number(b.credit) || 0}, 'Opening Balance', NOW())
          `;
        }
      }

      log.info('Opening balances posted', {
        entryId: entry.id,
        lines: balances.length,
        totalDebit,
        module: 'accounting',
      });

      return apiResponse.success(res, { journalEntry: entry });
    } catch (err) {
      log.error('Failed to save opening balances', { error: err, module: 'accounting' });
      return apiResponse.databaseError(res, err, 'Failed to save opening balances');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  const userId = (req as unknown as { user?: { id: string } }).user?.id || 'system';

  // Auto-generate invoice number
  const maxRows = (await sql`
    SELECT invoice_number FROM customer_invoices ORDER BY created_at DESC LIMIT 1
  `) as Row[];
  let nextNum = 1;
  if (maxRows.length > 0) {
    const match = maxRows[0].invoice_number?.match(/(\d+)$/);
    if (match) nextNum = parseInt(match[1], 10) + 1;
  }
  const invoiceNumber = `INV-${String(nextNum).padStart(5, '0')}`;

  // Calculate totals
  const rate = taxRate ?? 15;
  let subtotal = 0;
  for (const item of items) {
    subtotal += (item.quantity || 1) * item.unitPrice;
  }
  subtotal = Math.round(subtotal * 100) / 100;
  const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const today = new Date().toISOString().split('T')[0];
  const invDate = invoiceDate || today;
  const bpStart = billingPeriodStart || invDate;
  const bpEnd = billingPeriodEnd || invDate;

  // Find project from client (use first project if exists)
  const projRows = (await sql`
    SELECT id FROM projects WHERE client_id = ${clientId}::UUID LIMIT 1
  `) as Row[];
  const projectId = projRows[0]?.id || clientId;

  const invRows = (await sql`
    INSERT INTO customer_invoices (
      invoice_number, project_id, client_id, billing_period_start, billing_period_end,
      subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
      notes, status, created_by
    ) VALUES (
      ${invoiceNumber}, ${projectId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
      ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
      ${dueDate || null}, ${notes || null}, 'draft', ${userId}
    ) RETURNING id
  `) as Row[];

  const invoiceId = invRows[0].id;

  for (const item of items) {
    const lineTotal = Math.round((item.quantity || 1) * item.unitPrice * 100) / 100;
    const lineTax = Math.round(lineTotal * (rate / 100) * 100) / 100;
    await sql`
      INSERT INTO customer_invoice_items (invoice_id, drop_number, description, unit_price, quantity, tax_amount, line_total, income_type)
      VALUES (${invoiceId}::UUID, ${item.dropNumber || 'MANUAL'}, ${item.description}, ${item.unitPrice},
        ${item.quantity || 1}, ${lineTax}, ${lineTotal}, ${item.incomeType || 'other'})
    `;
  }

  log.info('Customer invoice created', { invoiceNumber, totalAmount });
  return apiResponse.created(res, { id: invoiceId, invoiceNumber });
}

export default withAuth(withErrorHandler(handler));

/**
 * Bank Match Confirm API
 * POST /api/accounting/bank-match-confirm
 * Body: { bankTransactionId, candidateType, candidateId }
 * Confirms a manual match selection from the FindMatchModal.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  matchTransaction,
} from '@/modules/accounting/services/bankReconciliationService';
import type { CandidateType } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const {
    bankTransactionId,
    candidateType,
    candidateId,
  } = req.body as {
    bankTransactionId?: string;
    candidateType?: CandidateType;
    candidateId?: string;
  };

  // @ts-expect-error — auth middleware attaches user
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!candidateType) return apiResponse.badRequest(res, 'candidateType is required');
  if (!candidateId) return apiResponse.badRequest(res, 'candidateId is required');

  const validTypes: CandidateType[] = ['supplier_invoice', 'purchase_order', 'journal_line'];
  if (!validTypes.includes(candidateType)) {
    return apiResponse.badRequest(res, `candidateType must be one of: ${validTypes.join(', ')}`);
  }

  try {
    if (candidateType === 'supplier_invoice') {
      // Look up the supplier invoice to derive the supplier entity id
      const invRows = (await sql`
        SELECT id, supplier_id, total_amount FROM supplier_invoices WHERE id = ${candidateId}::UUID
      `) as Row[];
      if (invRows.length === 0) {
        return apiResponse.notFound(res, 'Supplier invoice', candidateId);
      }
      const inv = invRows[0]!;
      const supplierId = String(inv.supplier_id);

      // Allocate the bank transaction against the AP account for this supplier
      await allocateTransaction(
        bankTransactionId,
        '', // contraAccountId unused when allocType is 'supplier'
        userId,
        undefined,
        'supplier',
        supplierId,
      );

      // Mark invoice as paid
      await sql`
        UPDATE supplier_invoices SET status = 'paid', updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: supplier invoice', { bankTransactionId, candidateId }, 'accounting-api');
    } else if (candidateType === 'purchase_order') {
      // Look up the PO to derive the supplier entity id
      const poRows = (await sql`
        SELECT id, supplier_id, total_amount FROM purchase_orders WHERE id = ${candidateId}::UUID
      `) as Row[];
      if (poRows.length === 0) {
        return apiResponse.notFound(res, 'Purchase order', candidateId);
      }
      const po = poRows[0]!;
      const supplierId = String(po.supplier_id);

      // Allocate against AP account for this supplier
      await allocateTransaction(
        bankTransactionId,
        '',
        userId,
        undefined,
        'supplier',
        supplierId,
      );

      // Link PO to bank transaction and mark as paid
      await sql`
        UPDATE purchase_orders
        SET bank_transaction_id = ${bankTransactionId}::UUID,
            status = 'paid',
            updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      // Link bank transaction back to the PO
      await sql`
        UPDATE bank_transactions
        SET linked_po_id = ${candidateId}::UUID, updated_at = NOW()
        WHERE id = ${bankTransactionId}::UUID
      `;

      log.info('Confirmed match: purchase order', { bankTransactionId, candidateId }, 'accounting-api');
    } else {
      // journal_line — use the existing matchTransaction function
      await matchTransaction(bankTransactionId, candidateId);
      log.info('Confirmed match: journal line', { bankTransactionId, candidateId }, 'accounting-api');
    }

    return apiResponse.success(res, { matched: true, candidateType, candidateId });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Match confirmation failed';
    log.error('Failed to confirm bank match', { bankTransactionId, candidateType, candidateId, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Reconciliation Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { detectBankFormat, parseFNBStatement, parseStandardBankStatement, parseNedbankStatement, parseABSAStatement, parseCapitecStatement } from '../utils/bankCsvParsers';
import { parseOfxStatement } from '../utils/bankOfxParser';
import { parseQifStatement } from '../utils/bankQifParser';
import { runAutoMatch } from '../utils/autoMatch';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import type { BankTransaction, BankReconciliation, AutoMatchResult, BankFormat, BankCsvParseResult } from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Import ───────────────────────────────────────────────────────────────────

export async function importBankStatement(
  csvContent: string,
  bankAccountId: string,
  statementDate: string,
  bankFormat?: BankFormat
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    const format = bankFormat && bankFormat !== 'unknown' ? bankFormat : detectBankFormat(csvContent);
    let parseResult;

    switch (format) {
      case 'fnb':
        parseResult = parseFNBStatement(csvContent);
        break;
      case 'standard_bank':
        parseResult = parseStandardBankStatement(csvContent);
        break;
      case 'nedbank':
        parseResult = parseNedbankStatement(csvContent);
        break;
      case 'absa':
        parseResult = parseABSAStatement(csvContent);
        break;
      case 'capitec':
        parseResult = parseCapitecStatement(csvContent);
        break;
      case 'ofx':
        parseResult = parseOfxStatement(csvContent);
        break;
      case 'qif':
        parseResult = parseQifStatement(csvContent);
        break;
      default:
        throw new Error('Unable to detect bank format. Please specify the bank.');
    }

    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    for (const tx of parseResult.transactions) {
      await sql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `;
    }

    log.info('Imported bank statement', {
      batchId, format, count: parseResult.transactions.length,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import bank statement', { error: err }, 'accounting');
    throw err;
  }
}

// ── Import from Pre-Parsed Result (PDF) ──────────────────────────────────────

/**
 * Persist an already-parsed set of transactions (e.g. from a PDF import).
