/**
 * Supplier Categories API
 * GET: List categories with supplier count
 * POST: Create category
 * PUT: Update category
 * DELETE: Remove category
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {

  try {
    if (req.method === 'GET') {
      const rows = (await sql`
        SELECT sc.id, sc.name, sc.description, sc.created_at,
               COUNT(s.id)::int AS supplier_count
        FROM supplier_categories sc
        LEFT JOIN suppliers s ON LOWER(s.category) = LOWER(sc.name)
        GROUP BY sc.id
        ORDER BY sc.name
      `) as Row[];
      return apiResponse.success(res, rows.map((r: Row) => ({
        id: r.id, name: r.name, description: r.description || '',
        supplierCount: Number(r.supplier_count) || 0,
      })));
    }

    if (req.method === 'POST') {
      const { name, description } = req.body;
      if (!name?.trim()) return apiResponse.badRequest(res, 'Name is required');
      const rows = (await sql`
        INSERT INTO supplier_categories (name, description)
        VALUES (${name.trim()}, ${description || ''})
        RETURNING id, name, description
      `) as Row[];
      return apiResponse.success(res, rows[0]);
    }

    if (req.method === 'PUT') {
      const { id, name, description } = req.body;
      if (!id || !name?.trim()) return apiResponse.badRequest(res, 'ID and name are required');
      await sql`
        UPDATE supplier_categories
        SET name = ${name.trim()}, description = ${description || ''}
        WHERE id = ${id}
      `;
      return apiResponse.success(res, { id, name, description });
    }

    if (req.method === 'DELETE') {
      const { id } = req.body;
      if (!id) return apiResponse.badRequest(res, 'ID is required');
      await sql`DELETE FROM supplier_categories WHERE id = ${id}`;
      return apiResponse.success(res, { deleted: true });
    }

    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) {
      return apiResponse.success(res, []);
    }
    log.error('supplier-categories API error', { error: message });
    return apiResponse.internalError(res, err, 'Failed to process request');
  }
});

/**
 * VAT Adjustments Export API
 * GET — export VAT adjustments as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const rows = await sql`
      SELECT adjustment_number, adjustment_date, vat_period,
        adjustment_type, amount, reason, status
      FROM vat_adjustments ORDER BY adjustment_date DESC
    `;

    const csvLines = [
      'Adjustment No,Date,VAT Period,Type,Amount,Reason,Status',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.adjustment_number)),
        csvCell(String(r.adjustment_date)),
        csvCell(String(r.vat_period || '')),
        csvCell(String(r.adjustment_type)),
        Number(r.amount || 0).toFixed(2),
        csvCell(String(r.reason || '')),
        csvCell(String(r.status)),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="vat-adjustments-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('VAT adjustments export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export VAT adjustments');
  }
}

export default withAuth(handler);

/**
 * Year-End Export API
 * GET — export fiscal year summaries as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const rows = await sql`
      SELECT fiscal_year, MIN(start_date) AS start_date, MAX(end_date) AS end_date,
        CASE WHEN COUNT(*) FILTER (WHERE status = 'open') > 0 THEN 'open' ELSE 'closed' END AS status
      FROM fiscal_periods
      GROUP BY fiscal_year
      ORDER BY fiscal_year DESC
    `;

    const csvLines = [
      'Year,Start Date,End Date,Status',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.fiscal_year)),
        csvCell(String(r.start_date)),
        csvCell(String(r.end_date)),
        csvCell(String(r.status)),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="year-end-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Year-end export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export year-end data');
  }
}

export default withAuth(handler);

