/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  const userId = (req as unknown as { user?: { id: string } }).user?.id || 'system';

  // Calculate totals
  const rate = taxRate ?? 15;
  let subtotal = 0;
  for (const item of items) {
    subtotal += (item.quantity || 1) * item.unitPrice;
  }
  subtotal = Math.round(subtotal * 100) / 100;
  const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const today = new Date().toISOString().split('T')[0];
  const invDate = invoiceDate || today;
  const bpStart = billingPeriodStart || invDate;
  const bpEnd = billingPeriodEnd || invDate;

  // Find project from client (use first project if exists)
  const projRows = (await sql`
    SELECT id FROM projects WHERE client_id = ${clientId}::UUID LIMIT 1
  `) as Row[];
  const projectId = projRows[0]?.id || clientId;

  // Insert invoice header and all line items atomically
  let invoiceId: string;

  await sql`BEGIN`;
  try {
    const invRows = (await sql`
      INSERT INTO customer_invoices (
        invoice_number, project_id, client_id, billing_period_start, billing_period_end,
        subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
        notes, status, created_by
      ) VALUES (
        ${invoiceNumber}, ${projectId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
        ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
        ${dueDate || null}, ${notes || null}, 'draft', ${userId}
      ) RETURNING id
    `) as Row[];

    invoiceId = invRows[0].id;

    for (const item of items) {
      const lineTotal = Math.round((item.quantity || 1) * item.unitPrice * 100) / 100;
      const lineTax = Math.round(lineTotal * (rate / 100) * 100) / 100;
      await sql`
        INSERT INTO customer_invoice_items (invoice_id, drop_number, description, unit_price, quantity, tax_amount, line_total, income_type)
        VALUES (${invoiceId}::UUID, ${item.dropNumber || 'MANUAL'}, ${item.description}, ${item.unitPrice},
          ${item.quantity || 1}, ${lineTax}, ${lineTotal}, ${item.incomeType || 'other'})
      `;
    }

    await sql`COMMIT`;
  } catch (txErr) {
    await sql`ROLLBACK`;
    throw txErr;
  }

  log.info('Customer invoice created', { invoiceNumber, totalAmount });
  return apiResponse.created(res, { id: invoiceId, invoiceNumber });
}

export default withAuth(withErrorHandler(handler));

/**
 * Sales by Customer Report API
 * GET: Returns sales summary grouped by customer for a date range
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withErrorHandler } from '@/lib/api-error-handler';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        ci.client_id,
        c.company_name AS client_name,
        COUNT(ci.id)::int AS invoice_count,
        COALESCE(SUM(ci.total_amount), 0)::numeric AS total_sales,
        COALESCE(SUM(ci.amount_paid), 0)::numeric AS payments_received,
        COALESCE(SUM(ci.total_amount - ci.amount_paid), 0)::numeric AS outstanding
      FROM customer_invoices ci
      JOIN clients c ON c.id = ci.client_id
      WHERE ci.invoice_date >= ${from}
        AND ci.invoice_date <= ${to}
        AND ci.status != 'cancelled'
      GROUP BY ci.client_id, c.company_name
      ORDER BY total_sales DESC
    `;

    const data = rows.map(r => ({
      clientId: r.client_id,
      clientName: r.client_name,
      invoiceCount: Number(r.invoice_count),
      totalSales: Number(r.total_sales),
      paymentsReceived: Number(r.payments_received),
      outstanding: Number(r.outstanding),
    }));

    if (format === 'csv') {
      const header = 'Customer,Invoices,Total Sales,Received,Outstanding';
      const csvRows = data.map(r =>
        `"${r.clientName}",${r.invoiceCount},${r.totalSales.toFixed(2)},${r.paymentsReceived.toFixed(2)},${r.outstanding.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="sales-by-customer-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('sales-by-customer report error', { error: message });
    return apiResponse.internalError(res, err instanceof Error ? err : new Error('Failed to generate report'));
  }
});

/**
 * Sales by Item Report API
 * GET: Sales analysis grouped by item for a date range
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withErrorHandler } from '@/lib/api-error-handler';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        cii.description AS name,
        cii.income_type AS category,
        COUNT(cii.id)::int AS times_sold,
        COALESCE(SUM(cii.quantity), 0)::numeric AS qty_sold,
        COALESCE(SUM(cii.line_total), 0)::numeric AS total_revenue
      FROM customer_invoice_items cii
      JOIN customer_invoices ci ON ci.id = cii.invoice_id
      WHERE ci.invoice_date >= ${from}
        AND ci.invoice_date <= ${to}
        AND ci.status != 'cancelled'
      GROUP BY cii.description, cii.income_type
      ORDER BY total_revenue DESC
    `;

    const data = rows.map(r => ({
      id: '',
      itemCode: '',
      name: r.name || 'Unnamed',
      category: r.category || '',
      timesSold: Number(r.times_sold),
      qtySold: Number(r.qty_sold),
      totalRevenue: Number(r.total_revenue),
      avgPrice: Number(r.qty_sold) > 0 ? Number(r.total_revenue) / Number(r.qty_sold) : 0,
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Category,Times Sold,Qty Sold,Total Revenue,Avg Price';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.category}",${r.timesSold},${r.qtySold},${r.totalRevenue.toFixed(2)},${r.avgPrice.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="sales-by-item-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Sales by item report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

