/**
 * Purchases by Supplier Report API
 * GET: Returns purchase summary grouped by supplier for a date range
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';

const sql = neon(process.env.DATABASE_URL!);
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        si.supplier_id,
        s.company_name AS supplier_name,
        COUNT(si.id)::int AS invoice_count,
        COALESCE(SUM(si.total_amount), 0)::numeric AS total_purchases,
        COALESCE(SUM(si.amount_paid), 0)::numeric AS payments_made,
        COALESCE(SUM(si.total_amount - si.amount_paid), 0)::numeric AS outstanding
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.invoice_date >= ${from}
        AND si.invoice_date <= ${to}
        AND si.status != 'cancelled'
      GROUP BY si.supplier_id, s.company_name
      ORDER BY total_purchases DESC
    `;

    const data = rows.map(r => ({
      supplierId: r.supplier_id,
      supplierName: r.supplier_name,
      invoiceCount: Number(r.invoice_count),
      totalPurchases: Number(r.total_purchases),
      paymentsMade: Number(r.payments_made),
      outstanding: Number(r.outstanding),
    }));

    if (format === 'csv') {
      const header = 'Supplier,Invoices,Total Purchases,Paid,Outstanding';
      const csvRows = data.map(r =>
        `"${r.supplierName}",${r.invoiceCount},${r.totalPurchases.toFixed(2)},${r.paymentsMade.toFixed(2)},${r.outstanding.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="purchases-by-supplier-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('purchases-by-supplier report error', { error: message });
    return apiResponse.error(res, 'Failed to generate report');
  }
});

/**
 * Sales by Customer Report API
 * GET: Returns sales summary grouped by customer for a date range
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';

const sql = neon(process.env.DATABASE_URL!);
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        ci.client_id,
        c.company_name AS client_name,
        COUNT(ci.id)::int AS invoice_count,
        COALESCE(SUM(ci.total_amount), 0)::numeric AS total_sales,
        COALESCE(SUM(ci.amount_paid), 0)::numeric AS payments_received,
        COALESCE(SUM(ci.total_amount - ci.amount_paid), 0)::numeric AS outstanding
      FROM customer_invoices ci
      JOIN clients c ON c.id = ci.client_id
      WHERE ci.invoice_date >= ${from}
        AND ci.invoice_date <= ${to}
        AND ci.status != 'cancelled'
      GROUP BY ci.client_id, c.company_name
      ORDER BY total_sales DESC
    `;

    const data = rows.map(r => ({
      clientId: r.client_id,
      clientName: r.client_name,
      invoiceCount: Number(r.invoice_count),
      totalSales: Number(r.total_sales),
      paymentsReceived: Number(r.payments_received),
      outstanding: Number(r.outstanding),
    }));

    if (format === 'csv') {
      const header = 'Customer,Invoices,Total Sales,Received,Outstanding';
      const csvRows = data.map(r =>
        `"${r.clientName}",${r.invoiceCount},${r.totalSales.toFixed(2)},${r.paymentsReceived.toFixed(2)},${r.outstanding.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="sales-by-customer-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('sales-by-customer report error', { error: message });
    return apiResponse.error(res, 'Failed to generate report');
  }
});

