/**
 * Supplier Statement Detail API
 * GET /api/accounting/supplier-statement-detail?supplier_id=UUID
 * Returns full transaction history (invoices, payments, returns) with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/db.mjs';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

/** Load VAT rate from app_settings, falling back to 15% */
async function getVatRate(): Promise<number> {
  try {
    const rows = (await sql`SELECT value FROM app_settings WHERE key = 'vat_rate'`) as Row[];
    if (rows[0]?.value) {
      const rate = Number(rows[0].value);
      if (rate > 0 && rate < 1) return rate;
    }
  } catch { /* use default */ }
  return DEFAULT_VAT_RATE;
}

if (inv.is_drc) throw new Error('DRC VAT already applied to this invoice');

const totalExclVat = Number(inv.total_amount);
const vatRate = await getVatRate();
const vatAmount = Math.round(totalExclVat * vatRate * 100) / 100;

return rows.map((r: Row) => ({
  id: String(r.id),
  invoiceNumber: String(r.invoice_number),
  supplierName: String(r.supplier_name || 'Unknown'),
  totalAmount: Number(r.total_amount),
  vatAmount: Math.round(Number(r.total_amount) * vatRate * 100) / 100,
  invoiceDate: String(r.invoice_date).split('T')[0],
}));

// Check if already posted
const inv = (await sql`
  SELECT id, invoice_number, total_amount, tax_amount, subtotal, gl_journal_entry_id
  FROM customer_invoices WHERE id = ${invoiceId}
`) as Row[];

if (!inv[0]) { log.warn('Invoice not found for GL posting', { invoiceId }, 'accounting'); return null; }
if (inv[0].gl_journal_entry_id) return String(inv[0].gl_journal_entry_id); // Already posted

const totalAmount = Number(inv[0].total_amount || 0);
const taxAmount = Number(inv[0].tax_amount || 0);
const subtotal = Number(inv[0].subtotal || totalAmount - taxAmount);
if (totalAmount === 0) return null;

const arId = await getAccountId(ACCOUNTS.AR);
const revenueId = await getAccountId(ACCOUNTS.ACTIVATION_REVENUE);
const vatOutputId = await getAccountId(ACCOUNTS.VAT_OUTPUT);

// Create journal entry: DR AR (total), CR Revenue (subtotal), CR VAT Output (tax)
const entry = (await sql`
  INSERT INTO gl_journal_entries (
    entry_number, entry_date, description, source, status, created_by
  ) VALUES (
    ${`CI-${inv[0].invoice_number}`}, CURRENT_DATE,
    ${`Customer invoice ${inv[0].invoice_number} approved`},
    'auto_invoice', 'posted', ${userId}
  ) RETURNING id
`) as Row[];

