/**
 * Supplier Statement Detail API
 * GET /api/accounting/supplier-statement-detail?supplier_id=UUID
 * Returns full transaction history (invoices, payments, returns) with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

interface Transaction {
  id: number;
  date: string;
  type: 'invoice' | 'payment' | 'debit_note';
  reference: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
}

export default withAuth(withErrorHandler(async (req: NextApiRequest, res: NextApiResponse) => {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || '', ['GET']);

  const { supplier_id } = req.query;
  if (!supplier_id) return apiResponse.badRequest(res, 'supplier_id is required');

  try {
    // Get supplier info
    const supplierRows = await sql`
      SELECT id, name, email, phone FROM suppliers WHERE id = ${Number(supplier_id)}
    `;
    if (supplierRows.length === 0) return apiResponse.notFound(res, 'Supplier', supplier_id as string);
    const supplier = supplierRows[0] as { id: number; name: string; email: string | null; phone: string | null };

    // Get invoices
    const invoices = await sql`
      SELECT id, invoice_number as reference, invoice_date as date,
        total_amount as amount, amount_paid, notes as description
      FROM supplier_invoices
      WHERE supplier_id = ${Number(supplier_id)}
        AND status NOT IN ('cancelled', 'draft')
      ORDER BY invoice_date ASC
    `;

    // Get payments
    const payments = await sql`
      SELECT sp.id, sp.payment_number as reference, sp.payment_date as date,
        sp.total_amount as amount, sp.description
      FROM supplier_payments sp
      WHERE sp.supplier_id = ${Number(supplier_id)}
        AND sp.status NOT IN ('cancelled', 'draft')
      ORDER BY sp.payment_date ASC
    `;

    // Get debit notes (supplier returns)
    const returns = await sql`
      SELECT cn.id, cn.credit_note_number as reference, cn.credit_date as date,
        cn.total_amount as amount, cn.reason as description
      FROM credit_notes cn
      WHERE cn.supplier_id = ${Number(supplier_id)}
        AND cn.type = 'supplier'
        AND cn.status NOT IN ('cancelled', 'draft')
      ORDER BY cn.credit_date ASC
    `;

    // Normalize date to YYYY-MM-DD regardless of input format
    function toISODate(val: unknown): string {
      if (!val) return '1970-01-01';
      if (val instanceof Date) return val.toISOString().split('T')[0];
      const s = String(val);
      if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0];
      const d = new Date(s);
      return isNaN(d.getTime()) ? '1970-01-01' : d.toISOString().split('T')[0];
    }

    // Merge into chronological transactions
    const transactions: Transaction[] = [];

    for (const inv of invoices as { id: number; reference: string; date: string; amount: number; description: string }[]) {
      transactions.push({
        id: inv.id,
        date: toISODate(inv.date),
        type: 'invoice',
        reference: inv.reference || '-',
        description: inv.description || 'Supplier Invoice',
        debit: Number(inv.amount),
        credit: 0,
        balance: 0,
      });
    }

    for (const pmt of payments as { id: number; reference: string; date: string; amount: number; description: string }[]) {
      transactions.push({
        id: pmt.id,
        date: toISODate(pmt.date),
        type: 'payment',
        reference: pmt.reference || '-',
        description: pmt.description || 'Payment',
        debit: 0,
        credit: Number(pmt.amount),
        balance: 0,
      });
    }

    for (const ret of returns as { id: number; reference: string; date: string; amount: number; description: string }[]) {
      transactions.push({
        id: ret.id,
        date: toISODate(ret.date),
        type: 'debit_note',
        reference: ret.reference || '-',
        description: ret.description || 'Debit Note',
        debit: 0,
        credit: Number(ret.amount),
        balance: 0,
      });
    }

    // Sort chronologically, invoices before payments on same date
    transactions.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      const typeOrder: Record<string, number> = { invoice: 0, debit_note: 1, payment: 2 };
      return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
    });

    // Calculate running balance
    let running = 0;
    for (const txn of transactions) {
      running += txn.debit - txn.credit;
      txn.balance = running;
    }

    const totalInvoiced = transactions.reduce((s, t) => s + t.debit, 0);
    const totalPaid = transactions.filter(t => t.type === 'payment').reduce((s, t) => s + t.credit, 0);
    const totalReturns = transactions.filter(t => t.type === 'debit_note').reduce((s, t) => s + t.credit, 0);

    return apiResponse.success(res, {
      supplier,
      transactions,
      summary: {
        totalInvoiced,
        totalPaid,
        totalReturns,
        balance: totalInvoiced - totalPaid - totalReturns,
      },
    });
  } catch (err) {
    log.error('Supplier statement detail failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to load supplier statement');
  }
}));

/**
 * Budget vs Actual Export API
 * GET — export budget vs actual report as CSV
 *
 * Replicates the date-range and budget-loading logic from reports-budget-vs-actual.ts
 * so the CSV matches exactly what the UI report shows.
 *
 * Query params:
 *   period   current | ytd | full_year   (default: ytd)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withErrorHandler } from '@/lib/api-error-handler';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

/** Escape a value for CSV — wraps in double-quotes and escapes internal quotes. */
function csvVal(value: string | number): string {
  const str = String(value);
  return `"${str.replace(/"/g, '""')}"`;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  const period = (req.query.period as string) || 'ytd';

  try {
    // Resolve date range — identical logic to reports-budget-vs-actual.ts
    let startDate: string;
    let endDate: string;
    const now = new Date();

    if (period === 'current') {
      startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0]!;
      endDate = now.toISOString().split('T')[0]!;
    } else {
      const fyRows = await sql`
        SELECT MIN(start_date) AS start_date, MAX(end_date) AS end_date
        FROM fiscal_periods
        WHERE fiscal_year = (
          SELECT fiscal_year FROM fiscal_periods
          WHERE status = 'open'
          ORDER BY start_date DESC
          LIMIT 1
        )
      `;
      const fy = fyRows[0];
      const fyStart = fy?.start_date instanceof Date
        ? fy.start_date.toISOString().split('T')[0]
        : (fy?.start_date ? String(fy.start_date).split('T')[0] : null);
      const fyEnd = fy?.end_date instanceof Date
        ? fy.end_date.toISOString().split('T')[0]
        : (fy?.end_date ? String(fy.end_date).split('T')[0] : null);
      startDate = fyStart || `${now.getFullYear()}-03-01`;
      endDate = period === 'full_year'
        ? (fyEnd || `${now.getFullYear() + 1}-02-28`)
        : now.toISOString().split('T')[0]!;
    }

    // Load budget amounts — from accounting_budgets table, falling back to app_settings
    let budgets: Record<string, number> = {};
    try {
      const fiscalYear = new Date(startDate).getFullYear();
      const startMonth = new Date(startDate).getMonth(); // 0-based
      const endMonth = new Date(endDate).getMonth();
      const monthCols = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

      const budgetRows = await sql`
        SELECT ab.gl_account_id, ga.account_code,
          ab.jan, ab.feb, ab.mar, ab.apr, ab.may, ab.jun,
          ab.jul, ab.aug, ab.sep, ab.oct, ab.nov, ab.dec
        FROM accounting_budgets ab
        JOIN gl_accounts ga ON ga.id = ab.gl_account_id
        WHERE ab.fiscal_year = ${fiscalYear}
      `;
      for (const row of budgetRows) {
        let total = 0;
        for (let m = startMonth; m <= endMonth; m++) {
          const col = monthCols[m] as string;
          total += Number(row[col] || 0);
        }
        budgets[String(row.account_code)] = total;
        budgets[String(row.gl_account_id)] = total;
      }
    } catch (e) {
      log.warn('Budget table query failed, trying app_settings fallback', { error: e }, 'accounting');
      try {
        const [row] = await sql`SELECT value FROM app_settings WHERE key = 'accounting_budgets'`;
        if (row?.value) {
          budgets = typeof row.value === 'string' ? JSON.parse(String(row.value)) : (row.value as Record<string, number>);
        }
      } catch (e2) { log.warn('Budget app_settings fallback failed', { error: e2 }, 'accounting'); }
    }

    // Fetch actual GL amounts for expense and revenue accounts in the period
    const actuals = await sql`
      SELECT
        ga.id, ga.account_code, ga.account_name, ga.account_type,
        COALESCE(SUM(
          CASE
            WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit
            WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit
            ELSE jl.debit - jl.credit
          END
        ), 0)::numeric AS actual_amount
      FROM gl_accounts ga
      LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
      LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        AND je.status = 'posted'
        AND je.entry_date >= ${startDate}
        AND je.entry_date <= ${endDate}
      WHERE ga.level = 3
        AND ga.is_active = true
        AND ga.account_type IN ('expense', 'revenue')
      GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type
      ORDER BY ga.account_code
    `;

    let totalBudget = 0;
    let totalActual = 0;
    let totalVariance = 0;

    const csvLines: string[] = [
      'Account Code,Account Name,Budget,Actual,Variance,Variance %',
    ];

    for (const row of actuals) {
      const accountCode = String(row.account_code);
      const accountName = String(row.account_name);
      const budget = Number(budgets[accountCode] || budgets[String(row.id)] || 0);
      const actual = Number(row.actual_amount);
      const variance = budget - actual;
      const variancePct = budget > 0 ? (variance / budget) * 100 : 0;

      totalBudget += budget;
      totalActual += actual;
      totalVariance += variance;

      csvLines.push(
        `${csvVal(accountCode)},${csvVal(accountName)},${budget.toFixed(2)},${actual.toFixed(2)},${variance.toFixed(2)},${variancePct.toFixed(2)}`
      );
    }

    // Totals row
    const totalVariancePct = totalBudget > 0 ? (totalVariance / totalBudget) * 100 : 0;
    csvLines.push(
      `${csvVal('')},${csvVal('TOTALS')},${totalBudget.toFixed(2)},${totalActual.toFixed(2)},${totalVariance.toFixed(2)},${totalVariancePct.toFixed(2)}`
    );

    const csv = csvLines.join('\n');
    const filename = `budget-vs-actual-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Failed to export budget vs actual report', { error: msg });
    return apiResponse.badRequest(res, 'Failed to export budget vs actual report');
  }
}

export default withAuth(withErrorHandler(handler));

