/**
 * Bank Transfers API
 * POST /api/accounting/bank-transfers - Transfer between bank accounts
 * Creates a balanced journal entry: DR destination bank, CR source bank
 * Sage equivalent: Banking > Transfers
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { fromAccountId, toAccountId, amount, reference, transferDate } = req.body;

  if (!fromAccountId || !toAccountId || !amount) {
    return apiResponse.validationError(res, {
      fromAccountId: !fromAccountId ? 'Required' : undefined,
      toAccountId: !toAccountId ? 'Required' : undefined,
      amount: !amount ? 'Required' : undefined,
    });
  }

  if (fromAccountId === toAccountId) {
    return apiResponse.badRequest(res, 'Source and destination accounts must be different');
  }

  if (Number(amount) <= 0) {
    return apiResponse.badRequest(res, 'Transfer amount must be positive');
  }

  try {
    // Verify both accounts exist and are bank accounts
    const accounts = await sql`
      SELECT id, account_code, account_name, account_subtype
      FROM gl_accounts
      WHERE id IN (${fromAccountId}, ${toAccountId})
    `;

    if (accounts.length !== 2) {
      return apiResponse.badRequest(res, 'One or both accounts not found');
    }

    const fromAcct = accounts.find(a => a.id === fromAccountId);
    const toAcct = accounts.find(a => a.id === toAccountId);

    // Get current fiscal period
    const [period] = await sql`
      SELECT id FROM fiscal_periods
      WHERE status = 'open'
      ORDER BY start_date DESC
      LIMIT 1
    `;

    // Create journal entry and lines atomically
    const entryRef = reference || `Transfer: ${fromAcct?.account_name} → ${toAcct?.account_name}`;
    const txDate = transferDate || new Date().toISOString().split('T')[0];

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let entry: any;

    await sql`BEGIN`;
    try {
      const [insertedEntry] = await sql`
        INSERT INTO gl_journal_entries (
          id, entry_number, entry_date, description,
          source, status, fiscal_period_id,
          total_debit, total_credit,
          created_by, created_at
        ) VALUES (
          gen_random_uuid(),
          'TXF-' || LPAD((SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM 5) AS INTEGER)), 0) + 1 FROM gl_journal_entries WHERE entry_number LIKE 'TXF-%')::text, 4, '0'),
          ${txDate}, ${entryRef},
          'bank_transfer', 'posted', ${period?.id || null},
          ${Number(amount)}, ${Number(amount)},
          ${userId}, NOW()
        )
        RETURNING *
      `;
      entry = insertedEntry;

      // Create journal lines: DR destination, CR source
      await sql`
        INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
        VALUES
          (gen_random_uuid(), ${entry.id}, ${toAccountId}, ${Number(amount)}, 0, ${`Transfer from ${fromAcct?.account_name}`}, NOW()),
          (gen_random_uuid(), ${entry.id}, ${fromAccountId}, 0, ${Number(amount)}, ${`Transfer to ${toAcct?.account_name}`}, NOW())
      `;

      await sql`COMMIT`;
    } catch (txErr) {
      await sql`ROLLBACK`;
      throw txErr;
    }

    log.info('Bank transfer completed', {
      entryId: entry.id,
      from: fromAcct?.account_code,
      to: toAcct?.account_code,
      amount,
      module: 'accounting',
    });

    return apiResponse.success(res, {
      journalEntry: entry,
      message: `Transferred R${Number(amount).toFixed(2)} from ${fromAcct?.account_name} to ${toAcct?.account_name}`,
    });
  } catch (err) {
    log.error('Failed to process bank transfer', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to process bank transfer');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Customer Statement Detail API
 * GET /api/accounting/customer-statement-detail?client_id=UUID
 * Returns full transaction-level statement with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const clientId = req.query.client_id as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'client_id is required');
  }

  try {
    // Get client info
    const clientRows = (await sql`
      SELECT id, company_name, email, phone FROM clients WHERE id = ${clientId}::UUID
    `) as Row[];
    if (clientRows.length === 0) {
      return apiResponse.notFound(res, 'Client', clientId);
    }
    const client = clientRows[0];

    // Get invoices
    const invoices = (await sql`
      SELECT id, invoice_number, invoice_date, reference, total_amount, status
      FROM customer_invoices
      WHERE client_id = ${clientId}::UUID AND status != 'cancelled'
      ORDER BY invoice_date
    `) as Row[];

    // Get confirmed payments — includes both allocated and unallocated (bank-sourced)
    const payments = (await sql`
      SELECT cp.id, cp.payment_number, cp.payment_date, cp.bank_reference,
        COALESCE(SUM(cpa.amount_allocated), cp.total_amount) AS amount_allocated
      FROM customer_payments cp
      LEFT JOIN customer_payment_allocations cpa ON cpa.payment_id = cp.id
      WHERE cp.client_id = ${clientId}::UUID AND cp.status IN ('confirmed', 'reconciled')
      GROUP BY cp.id, cp.payment_number, cp.payment_date, cp.bank_reference, cp.total_amount
    `) as Row[];

    // Get approved customer credit notes
    const creditNotes = (await sql`
      SELECT id, credit_note_number, credit_date, reason, total_amount
      FROM credit_notes
      WHERE client_id = ${clientId}::UUID AND type = 'customer' AND status = 'approved'
    `) as Row[];

    // Normalize date to YYYY-MM-DD regardless of input format
    function toISODate(val: unknown): string {
      if (!val) return '1970-01-01';
      if (val instanceof Date) return val.toISOString().split('T')[0];
      const s = String(val);
      if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0];
      const d = new Date(s);
      return isNaN(d.getTime()) ? '1970-01-01' : d.toISOString().split('T')[0];
    }

    // Build transaction list
    interface Transaction {
      id: number | string;
      date: string;
      type: 'invoice' | 'payment' | 'credit_note';
      reference: string;
      description: string;
      debit: number;
      credit: number;
      balance: number;
    }

    const transactions: Transaction[] = [];

    for (const inv of invoices) {
      transactions.push({
        id: inv.id,
        date: toISODate(inv.invoice_date),
        type: 'invoice',
        reference: String(inv.invoice_number),
        description: inv.reference ? String(inv.reference) : '',
        debit: Number(inv.total_amount),
        credit: 0,
        balance: 0,
      });
    }

    for (const pmt of payments) {
      transactions.push({
        id: pmt.id,
        date: toISODate(pmt.payment_date),
        type: 'payment',
        reference: String(pmt.payment_number),
        description: pmt.bank_reference ? String(pmt.bank_reference) : '',
        debit: 0,
        credit: Number(pmt.amount_allocated),
        balance: 0,
      });
    }

    for (const cn of creditNotes) {
      transactions.push({
        id: cn.id,
        date: toISODate(cn.credit_date),
        type: 'credit_note',
        reference: String(cn.credit_note_number),
        description: cn.reason ? String(cn.reason) : '',
        debit: 0,
        credit: Number(cn.total_amount),
        balance: 0,
      });
    }

    // Sort chronologically, invoices before payments on same date
    transactions.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      const typeOrder: Record<string, number> = { invoice: 0, credit_note: 1, payment: 2 };
      return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
    });

    // Calculate running balance
    let runningBalance = 0;
    let totalInvoiced = 0;
    let totalPaid = 0;
    let totalCredits = 0;

    for (const txn of transactions) {
      runningBalance += txn.debit - txn.credit;
      txn.balance = runningBalance;
      totalInvoiced += txn.debit;
      if (txn.type === 'payment') totalPaid += txn.credit;
      if (txn.type === 'credit_note') totalCredits += txn.credit;
    }

    return apiResponse.success(res, {
      client: {
        id: String(client.id),
        name: String(client.company_name),
        email: client.email ? String(client.email) : null,
        phone: client.phone ? String(client.phone) : null,
      },
      transactions,
      summary: {
        totalInvoiced,
        totalPaid,
        totalCredits,
        balance: runningBalance,
      },
    });
  } catch (err) {
    log.error('Failed to fetch customer statement detail', { clientId, error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to fetch customer statement');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Budget vs Actual Report API
 * GET /api/accounting/reports-budget-vs-actual?period=current|ytd|full_year
 * Sage equivalent: Reports > Budget vs Actual
 *
 * Reads budgets from gl_accounts.budget_amount column (if exists)
 * or from app_settings key 'accounting_budgets'.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  try {
    const { period = 'ytd' } = req.query;

    // Determine date range
    let startDate: string;
    let endDate: string;
    const now = new Date();

    if (period === 'current') {
      startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
      endDate = now.toISOString().split('T')[0];
    } else {
      // YTD or full_year — use fiscal year start
      const [fy] = await sql`
        SELECT MIN(start_date) as start_date, MAX(end_date) as end_date
        FROM fiscal_periods
        WHERE fiscal_year = (SELECT fiscal_year FROM fiscal_periods WHERE status = 'open' ORDER BY start_date DESC LIMIT 1)
      `;
      startDate = fy?.start_date?.toString().split('T')[0] || `${now.getFullYear()}-03-01`;
      endDate = period === 'full_year'
        ? (fy?.end_date?.toString().split('T')[0] || `${now.getFullYear() + 1}-02-28`)
        : now.toISOString().split('T')[0];
    }

    // Load budgets from accounting_budgets table
    // Determine which month columns to sum based on period
    let budgets: Record<string, number> = {};
    try {
      const fiscalYear = new Date(startDate).getFullYear();
      const startMonth = new Date(startDate).getMonth(); // 0-based
      const endMonth = new Date(endDate).getMonth();
      const monthCols = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];

      const budgetRows = await sql`
        SELECT ab.gl_account_id, ga.account_code,
          ab.jan, ab.feb, ab.mar, ab.apr, ab.may, ab.jun,
          ab.jul, ab.aug, ab.sep, ab.oct, ab.nov, ab.dec
        FROM accounting_budgets ab
        JOIN gl_accounts ga ON ga.id = ab.gl_account_id
        WHERE ab.fiscal_year = ${fiscalYear}
      `;
      for (const row of budgetRows) {
        let total = 0;
        for (let m = startMonth; m <= endMonth; m++) {
          total += Number(row[monthCols[m]] || 0);
        }
        budgets[row.account_code] = total;
        budgets[row.gl_account_id] = total;
      }
    } catch (e) {
      log.warn('Budget table query failed, trying app_settings fallback', { error: e }, 'accounting');
      try {
        const [row] = await sql`SELECT value FROM app_settings WHERE key = 'accounting_budgets'`;
        if (row?.value) {
          budgets = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;
        }
      } catch (e2) { log.warn('Budget app_settings fallback failed', { error: e2 }, 'accounting'); }
    }

    // Get actual GL balances for expense and revenue accounts
    const actuals = await sql`
      SELECT
        ga.id, ga.account_code, ga.account_name, ga.account_type,
        COALESCE(SUM(
          CASE
            WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit
            WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit
            ELSE jl.debit - jl.credit
          END
        ), 0)::numeric as actual_amount
      FROM gl_accounts ga
      LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
      LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        AND je.status = 'posted'
        AND je.entry_date >= ${startDate}
        AND je.entry_date <= ${endDate}
      WHERE ga.level = 3
        AND ga.is_active = true
        AND ga.account_type IN ('expense', 'revenue')
      GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type
      ORDER BY ga.account_code
    `;

    const lines = actuals.map(a => {
      const budgetAmount = Number(budgets[a.account_code] || budgets[a.id] || 0);
      const actualAmount = Number(a.actual_amount);
      // Revenue: positive variance = good (actual > budget)
      // Expense: positive variance = good (actual < budget, i.e. under budget)
      const variance = a.account_type === 'revenue'
        ? actualAmount - budgetAmount
        : budgetAmount - actualAmount;
      const variancePct = budgetAmount > 0
        ? (variance / budgetAmount) * 100
        : actualAmount > 0 ? -100 : 0;

      return {
        account_code: a.account_code,
        account_name: a.account_name,
        account_type: a.account_type,
        budget_amount: budgetAmount,
        actual_amount: actualAmount,
        variance,
        variance_pct: variancePct,
      };
    });

    const report = {
      period: `${startDate} to ${endDate}`,
      lines,
      total_budget: lines.reduce((s, l) => s + l.budget_amount, 0),
      total_actual: lines.reduce((s, l) => s + l.actual_amount, 0),
      total_variance: lines.reduce((s, l) => s + l.variance, 0),
    };

    return apiResponse.success(res, { report });
  } catch (err) {
    log.error('Failed to generate budget vs actual report', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to generate budget vs actual report');
  }
}

export default withAuth(withErrorHandler(handler));

