/**
 * API Route: /api/activate/sync-oes-to-qfield
 *
 * Purpose: Sync OES activation data AND remaining drops to QFieldCloud as GeoJSON files
 * Method: POST
 *
 * This endpoint creates TWO layers per QField project:
 * 1. OES FF DD-MM-YYYY.geojson - Activated drops (in oes_activations) - ORANGE dots
 * 2. Remaining Drops DD-MM-YYYY.geojson - Unactivated drops (NOT in oes_activations) - GREEN dots
 *
 * Data is split by FibreFlow project and synced to the correct QField project via
 * the qfield_project_links mapping table. FT_Master_Progress gets all projects combined.
 *
 * Coordinate Source: drops table (Neon DB) - NOT OES/Nokia coordinates
 */

import type { NextApiRequest, NextApiResponse } from 'next';

import https from 'https';
import { log } from '@/lib/logger';
import { withAuth, withRole } from '@/lib/auth';
import pool from '@/lib/db';

const QFIELD_API_TOKEN = process.env.QFIELD_API_TOKEN;

// South Africa bounding box for coordinate validation
const SA_BOUNDS = {
  minLat: -35,
  maxLat: -22,
  minLon: 16,
  maxLon: 33,
};

interface OESPoint {
  drop_number: string;
  serial_number: string;
  activation_date: string;
  team: string;
  ont_rx_sig_dbm: number;
  current_ont_rx: number;
  status: string;
  latitude: number;
  longitude: number;
  project_id: string;
}

interface RemainingDrop {
  drop_number: string;
  project_name: string | null;
  address: string | null;
  latitude: number;
  longitude: number;
  project_id: string;
}

interface GeoJSONFeature {
  type: 'Feature';
  geometry: {
    type: 'Point';
    coordinates: [number, number];
  };
  properties: {
    drop_number: string;
    serial_number: string;
    activation_date: string;
    team: string;
    ont_rx_sig_dbm: number;
    current_ont_rx: number;
    status: string;
    label: string;
  };
}

interface GeoJSONFeatureCollection {
  type: 'FeatureCollection';
  features: GeoJSONFeature[];
  crs?: {
    type: 'name';
    properties: {
      name: string;
    };
  };
}

interface SyncTarget {
  qfieldProjectId: string;
  qfieldProjectName: string;
  ffProjectIds: string[];
}

/**
 * Get sync targets: each QField project and which FF project IDs it should receive.
 * Uses qfield_project_links to determine the mapping.
 */
async function getSyncTargets(): Promise<SyncTarget[]> {
  const result = await pool.query(`
    SELECT
      qp.qfield_project_id,
      qp.name AS qfield_name,
      ARRAY_AGG(qpl.fibreflow_project_id::text) AS ff_project_ids
    FROM qfield_projects qp
    INNER JOIN qfield_project_links qpl ON qpl.qfield_project_id = qp.id
    WHERE qp.is_active = true
      AND qp.sync_enabled = true
    GROUP BY qp.qfield_project_id, qp.name
    ORDER BY qp.is_default DESC, qp.name
  `);

  return result.rows.map((r: any) => ({
    qfieldProjectId: r.qfield_project_id,
    qfieldProjectName: r.qfield_name,
    ffProjectIds: r.ff_project_ids,
  }));
}

function toOESFeature(point: OESPoint): GeoJSONFeature {
  return {
    type: 'Feature',
    geometry: {
      type: 'Point',
      coordinates: [Number(point.longitude), Number(point.latitude)],
    },
    properties: {
      drop_number: point.drop_number,
      serial_number: point.serial_number,
      activation_date: point.activation_date,
      team: point.team,
      ont_rx_sig_dbm: point.ont_rx_sig_dbm || -40,
      current_ont_rx: point.current_ont_rx || -40,
      status: point.status,
      label: point.drop_number,
    },
  };
}

function toRemainingFeature(drop: RemainingDrop): GeoJSONFeature {
  return {
    type: 'Feature',
    geometry: {
      type: 'Point',
      coordinates: [Number(drop.longitude), Number(drop.latitude)],
    },
    properties: {
      drop_number: drop.drop_number,
      serial_number: '',
      activation_date: '',
      team: drop.project_name || 'Unknown',
      ont_rx_sig_dbm: 0,
      current_ont_rx: 0,
      status: 'Pending',
      label: drop.drop_number,
    },
  };
}

function makeFeatureCollection(features: GeoJSONFeature[]): GeoJSONFeatureCollection {
  return {
    type: 'FeatureCollection',
    features,
    crs: { type: 'name', properties: { name: 'EPSG:4326' } },
  };
}

function formatDate(d: Date): string {
  const yyyy = String(d.getFullYear());
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${dd}-${mm}-${yyyy}`;
}

/**
 * Upload file to QFieldCloud via multipart form data
 */
async function uploadFileToQFieldCloud(
  projectId: string,
  filename: string,
  content: string,
  contentType: string = 'application/geo+json'
): Promise<{ success: boolean; status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const boundary = `----FormBoundary${Date.now()}`;
    const fileBuffer = Buffer.from(content, 'utf-8');

    const formParts: Buffer[] = [];
    formParts.push(Buffer.from(
      `--${boundary}\r\n` +
      `Content-Disposition: form-data; name="file"; filename="${filename}"\r\n` +
      `Content-Type: ${contentType}\r\n\r\n`
    ));
    formParts.push(fileBuffer);
    formParts.push(Buffer.from('\r\n'));
    formParts.push(Buffer.from(`--${boundary}--\r\n`));

    const body = Buffer.concat(formParts);
    const url = new URL(`/api/v1/files/${projectId}/${filename}/`, 'https://qfield.fibreflow.app');

    const options: https.RequestOptions = {
      method: 'POST',
      headers: {
        'Authorization': `Token ${QFIELD_API_TOKEN}`,
        'Content-Type': `multipart/form-data; boundary=${boundary}`,
        'Content-Length': body.length,
      },
      rejectUnauthorized: false,
      timeout: 60000,
    };

    const req = https.request(url, options, (res) => {
      let responseBody = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => responseBody += chunk);
      res.on('end', () => {
        resolve({
          success: res.statusCode !== undefined && res.statusCode >= 200 && res.statusCode < 300,
          status: res.statusCode || 0,
          body: responseBody,
        });
      });
    });

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('QFieldCloud file upload timeout'));
    });

    req.write(body);
    req.end();
  });
}

/**
 * Delete file from QFieldCloud
 */
async function deleteFileFromQFieldCloud(
  projectId: string,
  filename: string
): Promise<{ success: boolean; status: number }> {
  return new Promise((resolve) => {
    const url = new URL(`/api/v1/files/${projectId}/${filename}/`, 'https://qfield.fibreflow.app');

    const options: https.RequestOptions = {
      method: 'DELETE',
      headers: {
        'Authorization': `Token ${QFIELD_API_TOKEN}`,
      },
      rejectUnauthorized: false,
      timeout: 30000,
    };

    const req = https.request(url, options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        resolve({
          success: res.statusCode !== undefined && (res.statusCode >= 200 && res.statusCode < 300 || res.statusCode === 404),
          status: res.statusCode || 0,
        });
      });
    });

    req.on('error', () => resolve({ success: false, status: 0 }));
    req.on('timeout', () => {
      req.destroy();
      resolve({ success: false, status: 0 });
    });

    req.end();
  });
}

async function uploadGeoJSON(
  projectId: string,
  geojson: GeoJSONFeatureCollection,
  filename: string
): Promise<void> {
  const content = JSON.stringify(geojson, null, 2);
  log.info('OESSync', `Uploading ${filename} to ${projectId} (${content.length} bytes, ${geojson.features.length} features)`);

  const result = await uploadFileToQFieldCloud(projectId, filename, content);
  if (!result.success) {
    throw new Error(`Upload failed: ${result.status} - ${result.body}`);
  }
}

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    const {
      reportDate,
      teamFilter,
      statusFilter = 'Active',
    } = req.body;

    // Step 1: Get sync targets from qfield_project_links
    const syncTargets = await getSyncTargets();

    if (syncTargets.length === 0) {
      return res.status(200).json({
        success: false,
        message: 'No QField projects with linked FibreFlow projects found. Populate qfield_project_links first.',
        totalPoints: 0,
      });
    }

    log.info('OESSync', `Starting project-split OES sync to ${syncTargets.length} QField project(s)`, {
      targets: syncTargets.map(t => `${t.qfieldProjectName} (${t.ffProjectIds.length} FF projects)`),
      reportDate, teamFilter,
    });

    // Step 2: Fetch ALL OES data with project_id
    let oesQuery = `
      SELECT
        oes.drop_number,
        oes.serial_number,
        oes.activation_date::text,
        oes.team,
        oes.ont_rx_sig_dbm,
        oes.current_ont_rx,
        oes.status,
        d.latitude,
        d.longitude,
        d.project_id::text
      FROM oes_activations oes
      INNER JOIN drops d ON oes.drop_id = d.id
      WHERE d.latitude IS NOT NULL
        AND d.longitude IS NOT NULL
        AND d.latitude != 0
        AND d.longitude != 0
        AND d.latitude BETWEEN ${SA_BOUNDS.minLat} AND ${SA_BOUNDS.maxLat}
        AND d.longitude BETWEEN ${SA_BOUNDS.minLon} AND ${SA_BOUNDS.maxLon}
    `;

    const queryParams: any[] = [];
    let paramIndex = 1;

    if (reportDate) {
      oesQuery += ` AND DATE(oes.activation_date) = $${paramIndex}`;
      queryParams.push(reportDate);
      paramIndex++;
    }

    if (teamFilter) {
      oesQuery += ` AND oes.team = $${paramIndex}`;
      queryParams.push(teamFilter);
      paramIndex++;
    }

    if (statusFilter && statusFilter !== 'All') {
      oesQuery += ` AND oes.status = $${paramIndex}`;
      queryParams.push(statusFilter);
      paramIndex++;
    }

    oesQuery += ' ORDER BY oes.drop_number';

    const oesResult = await pool.query(oesQuery, queryParams);
    const allOES: OESPoint[] = oesResult.rows;

    log.info('OESSync', `Found ${allOES.length} total OES points`);

    if (allOES.length === 0) {
      return res.status(200).json({
        success: false,
        message: 'No OES points found with valid coordinates',
        totalPoints: 0,
      });
    }

    // Step 3: Fetch ALL remaining drops with project_id
    const remainingResult = await pool.query(`
      SELECT
        d.drop_number,
        p.project_name,
        d.address,
        d.latitude,
        d.longitude,
        d.project_id::text
      FROM drops d
      LEFT JOIN projects p ON d.project_id = p.id
      WHERE d.latitude IS NOT NULL
        AND d.longitude IS NOT NULL
        AND d.latitude != 0
        AND d.longitude != 0
        AND d.latitude BETWEEN ${SA_BOUNDS.minLat} AND ${SA_BOUNDS.maxLat}
        AND d.longitude BETWEEN ${SA_BOUNDS.minLon} AND ${SA_BOUNDS.maxLon}
        AND NOT EXISTS (
          SELECT 1 FROM oes_activations oes WHERE oes.drop_id = d.id
        )
      ORDER BY d.drop_number
    `);
    const allRemaining: RemainingDrop[] = remainingResult.rows;

    log.info('OESSync', `Found ${allRemaining.length} total remaining (unactivated) drops`);

    // Step 4: Build per-project indexes for fast filtering
    const oesByProject = new Map<string, OESPoint[]>();
    for (const point of allOES) {
      const existing = oesByProject.get(point.project_id);
      if (existing) {
        existing.push(point);
      } else {
        oesByProject.set(point.project_id, [point]);
      }
    }

    const remainingByProject = new Map<string, RemainingDrop[]>();
    for (const drop of allRemaining) {
      const existing = remainingByProject.get(drop.project_id);
      if (existing) {
        existing.push(drop);
      } else {
        remainingByProject.set(drop.project_id, [drop]);
      }
    }

    // Report date for filenames
    let filenameDate: Date;
    if (reportDate) {
      filenameDate = new Date(reportDate);
    } else {
      const latestBatch = await pool.query(
        'SELECT report_date FROM oes_import_batches ORDER BY imported_at DESC LIMIT 1'
      );
      filenameDate = latestBatch.rows[0]?.report_date
        ? new Date(latestBatch.rows[0].report_date)
        : new Date();
    }

    const dateStr = formatDate(filenameDate);
    const oesFilename = `OES FF ${dateStr}.geojson`;
    const remainingFilename = `Remaining Drops ${dateStr}.geojson`;

    log.info('OESSync', `Using filenames: ${oesFilename}, ${remainingFilename}`);

    // Step 5: Sync to each QField project with only its linked FF project data
    const syncResults: {
      projectId: string;
      projectName: string;
      activatedCount: number;
      remainingCount: number;
      success: boolean;
      error?: string;
    }[] = [];

    for (const target of syncTargets) {
      try {
        // Collect features for this target's linked FF projects
        const oesFeatures: GeoJSONFeature[] = [];
        const remFeatures: GeoJSONFeature[] = [];

        for (const ffId of target.ffProjectIds) {
          const projectOES = oesByProject.get(ffId);
          if (projectOES) {
            for (const point of projectOES) {
              oesFeatures.push(toOESFeature(point));
            }
          }

          const projectRemaining = remainingByProject.get(ffId);
          if (projectRemaining) {
            for (const drop of projectRemaining) {
              remFeatures.push(toRemainingFeature(drop));
            }
          }
        }

        log.info('OESSync', `${target.qfieldProjectName}: ${oesFeatures.length} activated, ${remFeatures.length} remaining`);

        // Delete existing files
        await deleteFileFromQFieldCloud(target.qfieldProjectId, oesFilename).catch(() => {/* ignore */});
        await deleteFileFromQFieldCloud(target.qfieldProjectId, remainingFilename).catch(() => {/* ignore */});

        // Upload project-specific GeoJSON
        if (oesFeatures.length > 0) {
          await uploadGeoJSON(target.qfieldProjectId, makeFeatureCollection(oesFeatures), oesFilename);
        }

        if (remFeatures.length > 0) {
          await uploadGeoJSON(target.qfieldProjectId, makeFeatureCollection(remFeatures), remainingFilename);
        }

        // Update last_synced_at
        await pool.query(
          'UPDATE qfield_projects SET last_synced_at = NOW() WHERE qfield_project_id = $1',
          [target.qfieldProjectId]
        ).catch(() => {/* non-critical */});

        syncResults.push({
          projectId: target.qfieldProjectId,
          projectName: target.qfieldProjectName,
          activatedCount: oesFeatures.length,
          remainingCount: remFeatures.length,
          success: true,
        });

        log.info('OESSync', `Successfully synced ${target.qfieldProjectName}`);
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err);
        syncResults.push({
          projectId: target.qfieldProjectId,
          projectName: target.qfieldProjectName,
          activatedCount: 0,
          remainingCount: 0,
          success: false,
          error: errorMsg,
        });
        log.error('OESSync', `Failed to sync ${target.qfieldProjectName}`, err);
      }
    }

    const successCount = syncResults.filter(r => r.success).length;

    return res.status(200).json({
      success: successCount > 0,
      message: `Synced OES data to ${successCount}/${syncTargets.length} QField project(s) (project-split)`,
      totalOES: allOES.length,
      totalRemaining: allRemaining.length,
      syncResults,
      files: {
        activated: oesFilename,
        remaining: remainingFilename,
      },
    });
  } catch (error) {
    log.error('OESSync', 'Sync failed', error);
    return res.status(500).json({
      error: error instanceof Error ? error.message : 'Failed to sync OES data to QFieldCloud',
    });
  }
}

export default withAuth(withRole('admin')(handler));

