            WHERE table_schema = 'public' 
            AND table_name = 'livekit_meetings'
        `;

        if (tables.length > 0) {
            console.log('✅ Migration successful! livekit_meetings table exists.');
        } else {
            console.log('❌ Migration may have failed. Table not found.');
        }

        // Show table structure
