// 🟢 WORKING: Retrieve transcript for a specific meeting (VTT or plain text)
// Access is restricted to meeting participants; hein@velocityfibre.co.za bypasses the check
import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { neon } from '@neondatabase/serverless';
import { parseVttSpeakers } from '@/lib/graph/transcripts';

const sql = neon(process.env.DATABASE_URL!);

/** Shape of a meetings row as returned by the participant-filtered query */
interface MeetingTranscriptRow {
  id: number;
  raw_transcript: string | null;
  participants: string | null;
}

/** Shape of a meeting_transcripts fallback row */
interface StoredTranscriptRow {
  content: string;
  format: string;
}

/**
 * GET /api/meetings/[id]/transcript
 *
 * Returns the transcript for a meeting in both raw and structured (speaker-parsed) form.
 *
 * Access control:
 *   - hein@velocityfibre.co.za: unrestricted access
 *   - Other roles: must appear in the meeting's participants JSON array by email
 *
 * Response body:
 *   meetingId  — numeric meeting ID
 *   transcript — raw VTT or plain text string
 *   format     — 'vtt' | 'text'
 *   structured — parsed utterances (non-null only for VTT format)
 */
async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const isOwner = userEmail === 'hein@velocityfibre.co.za';

  if (!userEmail) {
    return apiResponse.forbidden(res, 'User email is required for transcript access');
  }

  const rawId = req.query.id;
  const meetingId = typeof rawId === 'string' ? Number(rawId) : NaN;

  if (isNaN(meetingId) || meetingId <= 0) {
    return apiResponse.badRequest(res, 'Invalid meeting ID');
  }

  try {
    // Fetch meeting row — owner gets unconditional access, others require participant match
    const rows = isOwner
      ? await sql`
          SELECT id, raw_transcript, participants
          FROM meetings
          WHERE id = ${meetingId}
        `
      : await sql`
          SELECT id, raw_transcript, participants
          FROM meetings
          WHERE id = ${meetingId}
            AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(participants) AS p
              WHERE LOWER(p->>'email') = ${userEmail}
            )
        `;

    const meeting = rows[0] as MeetingTranscriptRow | undefined;

    if (!meeting) {
      // Return 403 rather than 404 to avoid leaking meeting existence to non-participants
      return apiResponse.forbidden(res, 'Meeting not found or you are not a participant');
    }

    // Resolve transcript: inline column first, then meeting_transcripts fallback
    let transcript: string | null = (meeting.raw_transcript as string | null) ?? null;
    let format = 'text';

    if (!transcript) {
      const fallback = await sql`
        SELECT content, format
        FROM meeting_transcripts
        WHERE meeting_id = ${meetingId}
        ORDER BY created_at DESC
        LIMIT 1
      `;

      const fallbackRow = fallback[0] as StoredTranscriptRow | undefined;
      if (fallbackRow) {
        transcript = fallbackRow.content;
        format = fallbackRow.format ?? 'text';
      }
    }

    if (!transcript) {
      return apiResponse.notFound(res, 'Transcript', meetingId);
    }

    // Parse VTT into structured utterances for client convenience
    const structured = format === 'vtt' ? parseVttSpeakers(transcript) : null;

    return apiResponse.success(res, {
      meetingId,
      transcript,
      format,
      structured,
    });
  } catch (error: unknown) {
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

// 🟢 WORKING: Stream a meeting recording MP4 with Range request support for video seeking
// Access restricted to meeting participants; hein@velocityfibre.co.za bypasses the check
import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { neon } from '@neondatabase/serverless';
import { log } from '@/lib/logger';
import * as fs from 'fs';

const sql = neon(process.env.DATABASE_URL!);

const LOGGER = 'RecordingAPI';

/** Shape of the meeting row returned by the recording queries */
interface MeetingRecordingRow {
  id: number;
  recording_path: string | null;
  recording_size_bytes: number | null;
}

/**
 * GET /api/meetings/[id]/recording
 *
 * Streams the MP4 recording for a meeting with full Range request support,
 * enabling seek operations in standard HTML5 <video> elements.
 *
 * Access control:
 *   - hein@velocityfibre.co.za: unrestricted access
 *   - Other roles: must appear in the meeting's participants JSON array by email
 *
 * Supports:
 *   - Full file delivery (200 Content-Length)
 *   - Partial content via Range header (206 Content-Range) for video seeking
 */
async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'GET') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const isOwner = userEmail === 'hein@velocityfibre.co.za';

  if (!userEmail) {
    res.status(403).json({ error: 'User email is required for recording access' });
    return;
  }

  const rawId = req.query.id;
  const meetingId = typeof rawId === 'string' ? Number(rawId) : NaN;

  if (isNaN(meetingId) || meetingId <= 0) {
    res.status(400).json({ error: 'Invalid meeting ID' });
    return;
  }

  try {
    // Fetch recording metadata with participant-based access control
    const rows = isOwner
      ? await sql`
          SELECT id, recording_path, recording_size_bytes
          FROM meetings
          WHERE id = ${meetingId}
        `
      : await sql`
          SELECT id, recording_path, recording_size_bytes
          FROM meetings
          WHERE id = ${meetingId}
            AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(participants) AS p
              WHERE LOWER(p->>'email') = ${userEmail}
            )
        `;

    const meeting = rows[0] as MeetingRecordingRow | undefined;

    if (!meeting) {
      // Return 403 rather than 404 to avoid leaking meeting existence to non-participants
      res.status(403).json({ error: 'Meeting not found or you are not a participant' });
      return;
    }

    if (!meeting.recording_path) {
      res.status(404).json({ error: 'No recording available for this meeting' });
      return;
    }

    if (!fs.existsSync(meeting.recording_path)) {
      log.warn(
        'Recording file missing from disk',
        { meetingId, path: meeting.recording_path },
        LOGGER
      );
      res.status(404).json({ error: 'Recording file not found on disk' });
      return;
    }

    const stat = fs.statSync(meeting.recording_path);
    const fileSize = stat.size;
    const rangeHeader = req.headers.range;

    if (rangeHeader) {
      // Partial content response for Range requests (video seeking)
      const parts = rangeHeader.replace(/bytes=/, '').split('-');
      const start = parseInt(parts[0]!, 10);
      const end = parts[1] ? parseInt(parts[1], 10) : fileSize - 1;

      if (start >= fileSize || end >= fileSize || start > end) {
        res.status(416).json({ error: 'Requested range not satisfiable' });
        return;
      }

      const chunkSize = end - start + 1;

      res.writeHead(206, {
        'Content-Range': `bytes ${start}-${end}/${fileSize}`,
        'Accept-Ranges': 'bytes',
        'Content-Length': chunkSize,
        'Content-Type': 'video/mp4',
      });

      const stream = fs.createReadStream(meeting.recording_path, { start, end });
      stream.pipe(res);

      stream.on('error', (streamError: Error) => {
        log.error(
          'Recording stream error during Range read',
          { meetingId, error: streamError.message },
          LOGGER
        );
        // Headers already sent — cannot send a new error response
      });
    } else {
      // Full file delivery
      res.writeHead(200, {
        'Content-Length': fileSize,
        'Content-Type': 'video/mp4',
        'Accept-Ranges': 'bytes',
      });

      const stream = fs.createReadStream(meeting.recording_path);
      stream.pipe(res);

      stream.on('error', (streamError: Error) => {
        log.error(
          'Recording stream error during full read',
          { meetingId, error: streamError.message },
          LOGGER
        );
      });
    }
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Recording handler error', { meetingId, error: errorMsg }, LOGGER);
    res.status(500).json({ error: 'Failed to stream recording' });
  }
}

export default withAuth(handler);

/**
 * Fireflies.ai API Service
 * Fetches meeting transcripts and summaries
 */

const FIREFLIES_API_URL = 'https://api.fireflies.ai/graphql';

interface FirefliesSpeaker {
  id: number;
  name: string;
}

interface FirefliesAttendee {
  name: string | null;
  email: string | null;
  displayName: string | null;
}

interface FirefliesTranscript {
  id: string;
  title: string;
  date: string;
  duration: number;
  transcript_url: string;
  summary: {
    keywords: string[];
    action_items: string[];
    outline: string[];
  };
  speakers: FirefliesSpeaker[];
  participants: string[];
  meeting_attendees: FirefliesAttendee[];
}

export interface MergedParticipant {
  name: string;
  email: string;
  displayName: string;
}

/**
 * Merge speakers, meeting_attendees, and participants into a single deduplicated list.
 * Priority: speakers (have names from voice recognition) > meeting_attendees > participants (emails only)
 */
function mergeParticipants(transcript: FirefliesTranscript): MergedParticipant[] {
  const seen = new Set<string>();
  const result: MergedParticipant[] = [];

  // 1. Add unique speakers (deduplicated by name)
  if (transcript.speakers?.length) {
    for (const speaker of transcript.speakers) {
      const name = speaker.name?.trim();
      if (!name) continue;
      const key = name.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      result.push({ name, email: '', displayName: name });
    }
  }

  // 2. Add meeting_attendees not already covered by speakers
  if (transcript.meeting_attendees?.length) {
    for (const attendee of transcript.meeting_attendees) {
      const email = attendee.email?.trim() || '';
      const name = attendee.name?.trim() || '';
      const displayName = attendee.displayName?.trim() || '';
      const key = (name || email || displayName).toLowerCase();
      if (!key || seen.has(key)) continue;
      // Also check if email matches a known key
      if (email && seen.has(email.toLowerCase())) continue;
      seen.add(key);
      if (email) seen.add(email.toLowerCase());
      result.push({ name, email, displayName });
    }
  }

  // 3. Add participant emails not already covered
  if (transcript.participants?.length) {
    for (const email of transcript.participants) {
      const trimmed = email?.trim();
      if (!trimmed) continue;
      const key = trimmed.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      result.push({ name: '', email: trimmed, displayName: '' });
    }
  }

  return result;
}

export async function fetchFirefliesTranscripts(apiKey: string) {
  const query = `
    query {
      transcripts {
        id
        title
        date
        duration
        transcript_url
        summary {
          keywords
          action_items
          outline
        }
        speakers {
          id
          name
        }
        participants
        meeting_attendees {
          name
          email
          displayName
        }
      }
    }
  `;

  const response = await fetch(FIREFLIES_API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify({ query }),
  });

  if (!response.ok) {
    throw new Error(`Fireflies API error: ${response.statusText}`);
  }

  const data = await response.json();
  return data.data.transcripts as FirefliesTranscript[];
}

export async function syncFirefliesToNeon(apiKey: string, sql: any) {
  const transcripts = await fetchFirefliesTranscripts(apiKey);

  for (const transcript of transcripts) {
    const merged = mergeParticipants(transcript);

    await sql`
      INSERT INTO meetings (
        fireflies_id,
        title,
        meeting_date,
        duration,
        transcript_url,
        summary,
        participants,
        created_at,
        updated_at
      ) VALUES (
        ${transcript.id},
        ${transcript.title},
        TO_TIMESTAMP(${transcript.date} / 1000.0),
        ${Math.floor(transcript.duration || 0)},
        ${transcript.transcript_url},
        ${JSON.stringify(transcript.summary)},
        ${JSON.stringify(merged)},
        NOW(),
        NOW()
      )
      ON CONFLICT (fireflies_id)
      DO UPDATE SET
        title = ${transcript.title},
        meeting_date = TO_TIMESTAMP(${transcript.date} / 1000.0),
        duration = ${Math.floor(transcript.duration || 0)},
        transcript_url = ${transcript.transcript_url},
        summary = ${JSON.stringify(transcript.summary)},
        participants = ${JSON.stringify(merged)},
        updated_at = NOW()
    `;
  }

  return transcripts.length;
}

