import { log } from '@/lib/logger';
import * as fs from 'fs';

const sql = neon(process.env.DATABASE_URL!);

const LOGGER = 'RecordingAPI';

/** Shape of the meeting row returned by the recording queries */
interface MeetingRecordingRow {
  id: number;
  recording_path: string | null;
  recording_size_bytes: number | null;
  audio_url: string | null;
  video_url: string | null;
}

/**
 * GET /api/meetings/[id]/recording
 *
 * Streams the MP4 recording for a meeting with full Range request support,
 * enabling seek operations in standard HTML5 <video> elements.
 *
 * Access control:
 *   - hein@velocityfibre.co.za: unrestricted access
 *   - Other roles: must appear in the meeting's participants JSON array by email
 *
 * Supports:
 *   - Full file delivery (200 Content-Length)
 *   - Partial content via Range header (206 Content-Range) for video seeking
 */
async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'GET') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const isOwner = userEmail === 'hein@velocityfibre.co.za';

  if (!userEmail) {
    res.status(403).json({ error: 'User email is required for recording access' });
    return;
  }

  const rawId = req.query.id;
  const meetingId = typeof rawId === 'string' ? Number(rawId) : NaN;

  if (isNaN(meetingId) || meetingId <= 0) {
    res.status(400).json({ error: 'Invalid meeting ID' });
    return;
  }

  try {
    // Fetch recording metadata with participant-based access control
    const rows = isOwner
      ? await sql`
          SELECT id, recording_path, recording_size_bytes, audio_url, video_url
          FROM meetings
          WHERE id = ${meetingId}
        `
      : await sql`
          SELECT id, recording_path, recording_size_bytes, audio_url, video_url
          FROM meetings
          WHERE id = ${meetingId}
            AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(participants) AS p
              WHERE LOWER(p->>'email') = ${userEmail}
            )
        `;

    const meeting = rows[0] as MeetingRecordingRow | undefined;

    if (!meeting) {
      // Return 403 rather than 404 to avoid leaking meeting existence to non-participants
      res.status(403).json({ error: 'Meeting not found or you are not a participant' });
      return;
    }

    if (!meeting.recording_path) {
      res.status(404).json({ error: 'No recording available for this meeting' });
      return;
    }

    if (!fs.existsSync(meeting.recording_path)) {
      log.warn(
        'Recording file missing from disk',
        { meetingId, path: meeting.recording_path },
        LOGGER
      );
      res.status(404).json({ error: 'Recording file not found on disk' });
      return;
    }

    const stat = fs.statSync(meeting.recording_path);
    const fileSize = stat.size;
    const rangeHeader = req.headers.range;

    if (rangeHeader) {
      // Partial content response for Range requests (video seeking)
      const parts = rangeHeader.replace(/bytes=/, '').split('-');
      const start = parseInt(parts[0]!, 10);
      const end = parts[1] ? parseInt(parts[1], 10) : fileSize - 1;

      if (start >= fileSize || end >= fileSize || start > end) {
        res.status(416).json({ error: 'Requested range not satisfiable' });
        return;
      }

      const chunkSize = end - start + 1;

      res.writeHead(206, {
        'Content-Range': `bytes ${start}-${end}/${fileSize}`,
        'Accept-Ranges': 'bytes',
        'Content-Length': chunkSize,
        'Content-Type': 'video/mp4',
      });

      const stream = fs.createReadStream(meeting.recording_path, { start, end });
      stream.pipe(res);

      stream.on('error', (streamError: Error) => {
        log.error(
          'Recording stream error during Range read',
          { meetingId, error: streamError.message },
          LOGGER
        );
        // Headers already sent — cannot send a new error response
      });
    } else {
      // Full file delivery
      res.writeHead(200, {
        'Content-Length': fileSize,
        'Content-Type': 'video/mp4',
        'Accept-Ranges': 'bytes',
      });

      const stream = fs.createReadStream(meeting.recording_path);
      stream.pipe(res);

      stream.on('error', (streamError: Error) => {
        log.error(
          'Recording stream error during full read',
          { meetingId, error: streamError.message },
          LOGGER
        );
      });
    }
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Recording handler error', { meetingId, error: errorMsg }, LOGGER);
    res.status(500).json({ error: 'Failed to stream recording' });
  }
}

export default withAuth(handler);

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { neon } from '@neondatabase/serverless';
import { syncFirefliesToNeon } from '@/services/fireflies/firefliesService';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // Get user info for access control
  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const userName = authReq.user?.name?.toLowerCase() || '';
  const isOwner = userEmail === 'hein@velocityfibre.co.za';

  if (!userEmail) {
    return res.status(403).json({ error: 'User email required for meeting access' });
  }

  if (req.method === 'GET') {
    try {
      // Check if requesting a specific meeting by ID
      const { id, source } = req.query;

      if (id) {
        // Super admin can access any meeting, others need to be participants
        const [meeting] = isOwner
          ? await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email, join_url,
                user_notes,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE id = ${id}
            `
          : await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email, join_url,
                user_notes,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE id = ${id}
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(participants) AS p
                WHERE LOWER(p->>'email') = ${userEmail}
                   OR LOWER(p->>'name') = ${userName}
                   OR LOWER(p->>'displayName') = ${userName}
              )
            `;

        if (!meeting) {
          return res.status(403).json({ error: 'Not authorized to view this meeting' });
        }

        return res.status(200).json({ meeting });
      }

      // Source filter: ?source=teams|fireflies|all (default: all)
      const sourceFilter = typeof source === 'string' && source !== 'all' ? source : null;

      // Super admin sees all meetings, others only see meetings they participated in
      if (sourceFilter) {
        const meetings = isOwner
          ? await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email,
                user_notes,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE source = ${sourceFilter}
              ORDER BY meeting_date DESC
              LIMIT 50
            `
          : await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email,
                user_notes,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE source = ${sourceFilter}
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(participants) AS p
                WHERE LOWER(p->>'email') = ${userEmail}
                   OR LOWER(p->>'name') = ${userName}
                   OR LOWER(p->>'displayName') = ${userName}
              )
              ORDER BY meeting_date DESC
              LIMIT 50
            `;

        return res.status(200).json({ meetings });
      }

      const meetings = isOwner
        ? await sql`
            SELECT
              id, fireflies_id, title, meeting_date as date, duration,
              transcript_url, summary, participants, created_at, updated_at,
              source, processing_status, organizer_name, organizer_email,
              user_notes,
              (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
              (recording_path IS NOT NULL) as has_recording
            FROM meetings
            ORDER BY meeting_date DESC
            LIMIT 50
          `
        : await sql`
            SELECT
              id, fireflies_id, title, meeting_date as date, duration,
              transcript_url, summary, participants, created_at, updated_at,
              source, processing_status, organizer_name, organizer_email,
              user_notes,
              (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
              (recording_path IS NOT NULL) as has_recording
            FROM meetings
            WHERE EXISTS (
              SELECT 1 FROM jsonb_array_elements(participants) AS p
              WHERE LOWER(p->>'email') = ${userEmail}
                 OR LOWER(p->>'name') = ${userName}
                 OR LOWER(p->>'displayName') = ${userName}
            )
            ORDER BY meeting_date DESC
            LIMIT 50
          `;

      return res.status(200).json({ meetings });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      log.error('Error fetching meetings:', { error: errorMessage, userEmail });
      return res.status(500).json({ error: errorMessage });
    }
  }

  if (req.method === 'POST' && req.query.action === 'sync') {
    try {
      const apiKey = process.env.FIREFLIES_API_KEY;

      if (!apiKey) {
        return res.status(500).json({ error: 'FIREFLIES_API_KEY not configured' });
      }

      const count = await syncFirefliesToNeon(apiKey, sql);

      return res.status(200).json({
        success: true,
        synced: count,
        message: `Synced ${count} meetings from Fireflies`
      });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      log.error('Error syncing from Fireflies:', { error: errorMessage });
      return res.status(500).json({ error: errorMessage });
    }
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

export default withAuth(handler);

