export DATABASE_URL="postgresql://neondb_owner:npg_MIUZXrg1tEY0@ep-dry-night-a9qyh4sj-pooler.gwc.azure.neon.tech/neondb?sslmode=require" && FIREFLIES_API_KEY="894886b5-b232-4319-95c7-1296782e9ea6" node -e "
const { neon } = require('@neondatabase/serverless');
const sql = neon(process.env.DATABASE_URL);
const apiKey = process.env.FIREFLIES_API_KEY;

const FIREFLIES_API_URL = 'https://api.fireflies.ai/graphql';

(async () => {
  // Fetch transcripts with sentences
  const query = \`
    query {
      transcripts {
        id
        title
        date
        duration
        transcript_url
        audio_url
        video_url
        summary {
          keywords
          action_items
          outline
        }
        speakers { id name }
        participants
        meeting_attendees { name email displayName }
        sentences { text speaker_name start_time end_time }
      }
    }
  \`;

  console.log('Fetching from Fireflies API...');
  const response = await fetch(FIREFLIES_API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
    body: JSON.stringify({ query }),
  });

  const data = await response.json();
  if (data.errors) { console.error('API errors:', data.errors); return; }

  const transcripts = data.data.transcripts;
  console.log('Total transcripts from API:', transcripts.length);

  let withSentences = 0;
  let withAudio = 0;
  let withVideo = 0;

  for (const t of transcripts) {
    if (t.sentences?.length) withSentences++;
    if (t.audio_url) withAudio++;
    if (t.video_url) withVideo++;
