// 🟢 WORKING: Microsoft Graph API OAuth2 client-credentials auth with token caching
import { log } from '@/lib/logger';

/** Required environment configuration for Microsoft Graph API */
interface GraphConfig {
  tenantId: string;
  clientId: string;
  clientSecret: string;
}

/** In-memory token cache entry */
interface TokenCache {
  token: string;
  expiresAt: number;
}

/** Module-level token cache — survives across requests within the same Node.js process */
let tokenCache: TokenCache | null = null;

/**
 * Reads and validates Graph API credentials from environment variables.
 * Throws if any required variable is missing.
 */
export function getGraphConfig(): GraphConfig {
  const tenantId = process.env.GRAPH_TENANT_ID;
  const clientId = process.env.GRAPH_CLIENT_ID;
  const clientSecret = process.env.GRAPH_CLIENT_SECRET;

  if (!tenantId || !clientId || !clientSecret) {
    throw new Error(
      'Missing Graph API configuration: GRAPH_TENANT_ID, GRAPH_CLIENT_ID, GRAPH_CLIENT_SECRET required'
    );
  }

  return { tenantId, clientId, clientSecret };
}

/**
 * Returns a valid Graph API access token, using the cached token when possible.
 * Automatically refreshes 5 minutes before expiry.
 */
export async function getGraphAccessToken(): Promise<string> {
  // Return cached token if still valid (with 5-minute buffer)
  if (tokenCache && tokenCache.expiresAt > Date.now() + 300_000) {
    return tokenCache.token;
  }

  const config = getGraphConfig();
  const tokenUrl = `https://login.microsoftonline.com/${config.tenantId}/oauth2/v2.0/token`;

  const params = new URLSearchParams({
    client_id: config.clientId,
    client_secret: config.clientSecret,
    scope: 'https://graph.microsoft.com/.default',
    grant_type: 'client_credentials',
  });

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 30_000);

  try {
    const response = await fetch(tokenUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString(),
      signal: controller.signal,
    });

    clearTimeout(timeout);

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Graph OAuth failed: ${response.status} ${errorText}`);
    }

    const data = await response.json();
    tokenCache = {
      token: data.access_token as string,
      expiresAt: Date.now() + (data.expires_in as number) * 1000,
    };

    log.info('Graph access token acquired', { expiresIn: data.expires_in }, 'GraphAuth');
    return tokenCache.token;
  } catch (error: unknown) {
    clearTimeout(timeout);
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error('Graph OAuth token request timed out after 30s');
    }
    throw error;
  }
}

/**
 * Authenticated fetch wrapper for Microsoft Graph API endpoints.
 * Automatically injects the Bearer token and retries once on 401.
 *
 * @param url - Full Graph API URL
 * @param options - Standard fetch RequestInit options (headers will be merged)
 */
export async function graphFetch(url: string, options: RequestInit = {}): Promise<Response> {
  const token = await getGraphAccessToken();

  const response = await fetch(url, {
    ...options,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });

  // Retry once on 401 — token may have expired between cache check and use
  if (response.status === 401) {
    tokenCache = null;
    const freshToken = await getGraphAccessToken();
    return fetch(url, {
      ...options,
      headers: {
        Authorization: `Bearer ${freshToken}`,
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  return response;
}

// 🟢 WORKING: Resolve Graph user IDs to display names, emails, and FibreFlow user IDs
import { graphFetch } from './auth';
import { neon } from '@neondatabase/serverless';
import { log } from '@/lib/logger';
import type { CallRecord } from './call-records';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const sql = neon(process.env.DATABASE_URL!);

/** A Graph user resolved to their profile and optional FibreFlow identity */
export interface ResolvedParticipant {
  graphUserId: string;
  displayName: string;
  email: string;
  /** Set when the email matches a row in the FibreFlow `users` table */
  fibreflowUserId?: number;
}

/** Raw profile data cached per Graph user ID within a sync run */
interface GraphUserProfile {
  displayName: string;
  email: string;
}

/**
 * Module-level cache for Graph /users lookups.
 * Scoped to the current Node.js process — avoids redundant API calls
 * when processing multiple call records in one sync run.
 */
const userCache = new Map<string, GraphUserProfile>();

/**
 * Collects all unique Graph user IDs referenced in a call record
 * (organizer, participants, session callers/callees) and resolves each
 * to their display name, email, and optional FibreFlow user ID.
 *
 * @param callRecord - A fully expanded CallRecord (include sessions/segments for full coverage)
 * @returns Array of resolved participants — deduplicated by Graph user ID
 */
export async function resolveParticipants(
  callRecord: CallRecord
): Promise<ResolvedParticipant[]> {
  const userIds = new Set<string>();

  // Collect from organizer
  if (callRecord.organizer?.user?.id) {
    userIds.add(callRecord.organizer.user.id);
  }

  // Collect from flat participants list
  if (callRecord.participants) {
    for (const p of callRecord.participants) {
      if (p.user?.id) userIds.add(p.user.id);
    }
  }

  // Collect from session-level caller/callee pairs
  if (callRecord.sessions) {
    for (const session of callRecord.sessions) {
      if (session.caller?.user?.id) userIds.add(session.caller.user.id);
      if (session.callee?.user?.id) userIds.add(session.callee.user.id);
    }
  }

  const resolved: ResolvedParticipant[] = [];

  for (const userId of userIds) {
    let userInfo = userCache.get(userId);

    if (!userInfo) {
      try {
        const response = await graphFetch(
          `${GRAPH_BASE}/users/${userId}?$select=displayName,mail,userPrincipalName`
        );

        if (response.ok) {
          const data = await response.json();
          userInfo = {
            displayName: (data.displayName as string) || '',
            // Teams users may have mail or userPrincipalName — prefer mail
            email: ((data.mail as string) || (data.userPrincipalName as string) || '').toLowerCase(),
          };
          userCache.set(userId, userInfo);
        } else {
          log.warn(
            'Failed to resolve Graph user',
            { userId, status: response.status },
            'SpeakerResolver'
          );
          userInfo = { displayName: '', email: '' };
        }
      } catch (error: unknown) {
        log.warn(
          'Error resolving Graph user',
          { userId, error: error instanceof Error ? error.message : String(error) },
          'SpeakerResolver'
        );
        userInfo = { displayName: '', email: '' };
      }
    }

    const ffUser =
      userInfo.email ? await matchToFibreflowUser(userInfo.email) : null;

    resolved.push({
      graphUserId: userId,
      displayName: userInfo.displayName,
      email: userInfo.email,
      fibreflowUserId: ffUser?.id,
    });
  }

  return resolved;
}

/**
 * Looks up a FibreFlow user by email address (case-insensitive).
 * Returns null if no match is found.
 *
 * @param email - Lowercased email from Graph user profile
 */
async function matchToFibreflowUser(
  email: string
): Promise<{ id: number; name: string } | null> {
  const rows = await sql`
    SELECT id, CONCAT(first_name, ' ', last_name) as full_name
    FROM users
    WHERE LOWER(email) = LOWER(${email})
    LIMIT 1
  `;

  return rows[0] ? { id: rows[0].id as number, name: rows[0].full_name as string } : null;
}

// 🟢 WORKING: Microsoft Graph API transcript fetch and VTT parser
import { graphFetch } from './auth';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';

/** Metadata record for a single transcript file attached to a meeting */
export interface TranscriptMeta {
  id: string;
  createdDateTime: string;
  contentCorrelationId?: string;
}

/** A single speaker utterance extracted from a VTT transcript */
export interface ParsedUtterance {
  /** Offset in milliseconds from the start of the recording */
  startMs: number;
  /** Speaker display name extracted from the VTT <v> tag */
  speaker: string;
  /** Spoken text with VTT markup stripped */
  text: string;
}

/**
 * Resolves the Graph onlineMeeting ID for a meeting identified by its join URL.
 * Returns null if the meeting cannot be found (e.g. organizer mismatch).
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param joinUrl - The joinWebUrl from the callRecord
 */
export async function fetchOnlineMeetingId(
  organizerUserId: string,
  joinUrl: string
): Promise<string | null> {
  const encodedUrl = encodeURIComponent(joinUrl);
  const url = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings?$filter=joinWebUrl eq '${encodedUrl}'`;

  const response = await graphFetch(url);

  if (!response.ok) {
    log.warn(
      'Failed to fetch online meeting',
      { organizerUserId, status: response.status },
      'GraphTranscripts'
    );
    return null;
  }

  const data = await response.json();
  return (data.value as Array<{ id: string }>)?.[0]?.id ?? null;
}

/**
 * Lists all transcript metadata records for the given online meeting.
 * Returns an empty array if no transcripts exist or the request fails.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param onlineMeetingId - Graph onlineMeeting ID (from fetchOnlineMeetingId)
 */
export async function listTranscripts(
  organizerUserId: string,
  onlineMeetingId: string
): Promise<TranscriptMeta[]> {
  const url = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings/${onlineMeetingId}/transcripts`;
  const response = await graphFetch(url);

  if (!response.ok) {
    log.warn(
      'No transcripts found',
      { onlineMeetingId, status: response.status },
      'GraphTranscripts'
    );
    return [];
  }

  const data = await response.json();
  return (data.value as TranscriptMeta[]) || [];
}

/**
 * Downloads the raw VTT content for a specific transcript.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param meetingId - Graph onlineMeeting ID
 * @param transcriptId - ID of the transcript to download
 * @returns Raw VTT string
 */
export async function downloadTranscriptContent(
  organizerUserId: string,
  meetingId: string,
  transcriptId: string
): Promise<string> {
  const url = [
    `${GRAPH_BASE}/users/${organizerUserId}`,
    `/onlineMeetings/${meetingId}`,
    `/transcripts/${transcriptId}/content?$format=text/vtt`,
  ].join('');

  const response = await graphFetch(url, {
    headers: { Accept: 'text/vtt' },
  });

  if (!response.ok) {
    throw new Error(`Failed to download transcript: ${response.status}`);
  }

  return response.text();
}

/**
 * Parses a VTT string into structured utterances with speaker attribution.
 * Handles the Teams-flavoured VTT dialect that uses <v SpeakerName> inline tags.
 *
 * @param vtt - Raw WebVTT content
 * @returns Ordered array of utterances sorted by startMs
 */
export function parseVttSpeakers(vtt: string): ParsedUtterance[] {
  const utterances: ParsedUtterance[] = [];

  // VTT cue blocks are separated by blank lines
  const blocks = vtt.split(/\n\n+/);

  for (const block of blocks) {
    const lines = block.trim().split('\n');

    // Locate the cue timing line (contains "-->")
    const tsLine = lines.find(l => l.includes('-->'));
    if (!tsLine) continue;

    // Parse HH:MM:SS.mmm from the start timestamp
    const startMatch = tsLine.match(/^(\d{2}):(\d{2}):(\d{2})\.(\d{3})/);
    if (!startMatch) continue;

    // startMatch[1..4] are guaranteed non-undefined because we checked `!startMatch` above
    const startMs =
      parseInt(startMatch[1]!, 10) * 3_600_000 +
      parseInt(startMatch[2]!, 10) * 60_000 +
      parseInt(startMatch[3]!, 10) * 1_000 +
      parseInt(startMatch[4]!, 10);

    // Text payload follows the timestamp line
    const tsIndex = lines.indexOf(tsLine);
    const textLines = lines.slice(tsIndex + 1);
    const fullText = textLines.join(' ').trim();

    // Teams VTT uses <v DisplayName>text</v> markup for speaker attribution
    const speakerMatch = fullText.match(/<v\s+([^>]+)>/);
    // speakerMatch[1] is non-undefined when speakerMatch is truthy (capture group 1 always present)
    const speaker = speakerMatch ? speakerMatch[1]! : 'Unknown';
    const text = fullText.replace(/<\/?v[^>]*>/g, '').trim();

    if (text) {
      utterances.push({ startMs, speaker, text });
    }
  }

  return utterances;
}

// 🟢 WORKING: Microsoft Graph API recording download — streams MP4 to local disk
import { graphFetch } from './auth';
import { log } from '@/lib/logger';
import * as fs from 'fs';
import * as path from 'path';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';

/** Metadata record for a single recording attached to an online meeting */
export interface RecordingMeta {
  id: string;
  createdDateTime: string;
  contentCorrelationId?: string;
}

/** Result of a successful recording download */
export interface RecordingDownloadResult {
  /** Absolute path to the saved MP4 file */
  filePath: string;
  /** File size in bytes */
  sizeBytes: number;
}

/**
 * Lists all recording metadata records for the given online meeting.
 * Returns an empty array if no recordings exist or the request fails.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param onlineMeetingId - Graph onlineMeeting ID
 */
export async function listRecordings(
  organizerUserId: string,
  onlineMeetingId: string
): Promise<RecordingMeta[]> {
  const url = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings/${onlineMeetingId}/recordings`;
  const response = await graphFetch(url);

  if (!response.ok) {
    log.warn(
      'No recordings found',
      { onlineMeetingId, status: response.status },
      'GraphRecordings'
    );
    return [];
  }

  const data = await response.json();
  return (data.value as RecordingMeta[]) || [];
}

/**
 * Downloads a Teams meeting recording to the local filesystem as an MP4.
 * Files are organised under `$MEETING_RECORDINGS_PATH/YYYY/MM/<dbMeetingId>.mp4`.
 * The directory tree is created automatically if it does not exist.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param meetingId - Graph onlineMeeting ID
 * @param recordingId - ID of the specific recording to download
 * @param dbMeetingId - Primary key from the local `meetings` table (used as filename)
 * @returns Resolved file path and file size in bytes
 */
export async function downloadRecordingToDisk(
  organizerUserId: string,
  meetingId: string,
  recordingId: string,
  dbMeetingId: number
): Promise<RecordingDownloadResult> {
  const basePath =
    process.env.MEETING_RECORDINGS_PATH || '/home/velo/meeting-recordings';

  const now = new Date();
  const year = now.getFullYear().toString();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const dir = path.join(basePath, year, month);

  // Ensure target directory exists before writing
  fs.mkdirSync(dir, { recursive: true });

  const filePath = path.join(dir, `${dbMeetingId}.mp4`);

  const url = [
    `${GRAPH_BASE}/users/${organizerUserId}`,
    `/onlineMeetings/${meetingId}`,
    `/recordings/${recordingId}/content`,
  ].join('');

  const response = await graphFetch(url);

  if (!response.ok) {
    throw new Error(`Failed to download recording: ${response.status}`);
  }

  // Buffer the entire response in memory then write atomically
  const buffer = Buffer.from(await response.arrayBuffer());
  fs.writeFileSync(filePath, buffer);

  const sizeBytes = buffer.length;
  log.info(
    'Recording downloaded',
    { filePath, sizeBytes, dbMeetingId },
    'GraphRecordings'
  );

  return { filePath, sizeBytes };
}

